INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-2-1','The twelve months','Mười hai tháng','4000_ESSENTIAL_ENGLISH_WORDS_031.mp3',NULL,'00:00:00.000','00:01:52.200','4000-essential-english-words-2',0,0,31) */
	('An awful woman lived with her daughter and stepdaughter in her household','Một người phụ nữ đáng sợ sống cùng con gái ruột và đứa con riêng trong một căn nhà','00:00:03.200','00:00:08.600','4000-essential-english-words-2-1'),
	('She possessed feelings of hate for her stepdaughter, Anna','Bà có ác cảm với đứa con riêng, Anna','00:00:08.600','00:00:12.900','4000-essential-english-words-2-1'),
	('Anna worked while her stepsister did nothing','Anna làm việc trong khi người em không làm gì','00:00:12.900','00:00:16.900','4000-essential-english-words-2-1'),
	('On a cold January night, Anna\'s stepmother remarked, "Your stepsister desires flowers"','Vào đêm tháng Giêng lạnh lẽo, người mẹ kế dặn dò Anna: "Em con ao ước có những bông hoa"','00:00:16.900','00:00:24.000','4000-essential-english-words-2-1'),
	('"Go and find some"','"Vậy con hãy đi và tìm chúng về đây"','00:00:24.000','00:00:25.700','4000-essential-english-words-2-1'),
	('Anna wasn\'t anxious to walk through the chilled landscape','Anna không lo lắng mấy khi đi trong khoảng trời rét buốt','00:00:25.700','00:00:29.900','4000-essential-english-words-2-1'),
	('The cold air made her lungs burn','Khí trời lạnh giá đã khiến cô bé bị viêm phổi','00:00:29.900','00:00:32.900','4000-essential-english-words-2-1'),
	('She walked at a slow pace because of the snow','Cô bước chậm vì tuyết rơi','00:00:32.900','00:00:36.900','4000-essential-english-words-2-1'),
	('Soon she saw a group of people','Chẳng bao lâu cô thấy một nhóm người','00:00:36.900','00:00:39.700','4000-essential-english-words-2-1'),
	('It consisted of twelve men','Có mười hai người đàn ông','00:00:39.700','00:00:41.900','4000-essential-english-words-2-1'),
	('Anna told them about the flowers','Anna nói cho họ nghe về chuyện những bông hoa','00:00:41.900','00:00:44.900','4000-essential-english-words-2-1'),
	('One of the man said they were the twelve months and that they would help Anna','Một trong những người đàn ông này nói rằng họ là mười hai tháng và họ sẽ giúp Anna','00:00:44.900','00:00:50.000','4000-essential-english-words-2-1'),
	('January walked to her and made a motion with his hand','Tháng Một bước đến chỗ cô và tạo ra một phép chuyển trong bàn tay','00:00:50.000','00:00:54.000','4000-essential-english-words-2-1'),
	('The days of the month passed rapidly until it was February\'s turn','Các ngày trong tháng trôi qua nhanh cho đến lượt Tháng Hai','00:00:54.000','00:00:59.000','4000-essential-english-words-2-1'),
	('February also made the month speed up','Tháng Hai cũng làm phép cho trôi qua nhanh','00:00:59.000','00:01:02.800','4000-essential-english-words-2-1'),
	('Then March made the sun shine and flowers grew in the field',' Đến Tháng Ba tạo ra ánh nắng mặt trời cùng những bông hoa tơi tốt trên cánh đồng','00:01:02.800','00:01:07.800','4000-essential-english-words-2-1'),
	('Anna loaded her basket with so many flowers that she could hardly lift it','Anna đặt những bông hoa vào rổ nhiều đến nổi cô phải rất khó khăn để nhấc nó lên','00:01:07.800','00:01:13.800','4000-essential-english-words-2-1'),
	('Then she gave a quick but polite "thank you" to the twelve men and returned home','Sau đó cô cảm ơn nhanh một cách lịch sự "Cảm ơn" với mười hai người đàn ông và trở về nhà','00:01:13.800','00:01:19.800','4000-essential-english-words-2-1'),
	('She was very eager to show her stepmother all the flowers','Cô bé vô cùng háo hức để khoe với mẹ kế những bông hoa','00:01:19.800','00:01:24.800','4000-essential-english-words-2-1'),
	('Back at the house, she spilled the flowers onto the table','Trở về nhà, cô trải những bông hoa lên bàn','00:01:24.800','00:01:29.300','4000-essential-english-words-2-1'),
	('Then she told her stepmother about the twelve men','Rồi cô kể cho mẹ kế nghe về chuyện mười hai người đàn ông','00:01:29.300','00:01:33.300','4000-essential-english-words-2-1'),
	('Anna\'s stepmother and stepsister went to seek the twelve months','Mẹ kế của Anna và cô em gái đã cùng đi tìm mười hai người đàn ông','00:01:33.300','00:01:38.500','4000-essential-english-words-2-1'),
	('Their intent was to ask for gifts','Ý định của họ là để xin những món quà','00:01:38.500','00:01:41.800','4000-essential-english-words-2-1'),
	('They looked and looked','Họ tìm mãi, tìm mãi','00:01:41.800','00:01:44.000','4000-essential-english-words-2-1'),
	('They became very lost and never found their way home','Nhưng họ đã bị lạc và không bao giờ tìm thấy đường về nhà','00:01:44.000','00:01:48.800','4000-essential-english-words-2-1'),
	('Anna lived happily by herself','Anna sống hạnh phúc một mình','00:01:48.800','00:01:52.200','4000-essential-english-words-2-1'),

	/* (UUID(),'4000-essential-english-words-2-2','The dragon','Con rồng','4000_ESSENTIAL_ENGLISH_WORDS_032.mp3',NULL,'00:00:00.000','00:01:40.000','4000-essential-english-words-2',0,0,32) */
	('An evil dragon lived in a castle in the remote southern mountains','Có một con rồng hung ác sống trong một tòa lâu đài trên những ngọn núi phía Nam hẻo lánh','00:00:03.000','00:00:07.900','4000-essential-english-words-2-2'),
	('One day the monster landed in a town','Một ngày nọ, con quái vật đã hạ cánh xuống một ngôi làng','00:00:07.900','00:00:10.900','4000-essential-english-words-2-2'),
	('The dragon commanded the people, "Give me food now, or I will eat you"','Con rồng đã ra lệnh cho người dân "Hãy mau đưa thức ăn đến đây cho ta, nếu không ta sẽ ăn thịt các ngươi"','00:00:10.900','00:00:16.900','4000-essential-english-words-2-2'),
	('The dragon lifted its wings so that its lungs could be completely filled with hot steam, and breathed it upon the people','Con rồng nâng đôi cánh của nó lên để phổi nó có thể chứa đầy hơi nóng và thổi hơi nóng đó vào người dân','00:00:16.900','00:00:25.900','4000-essential-english-words-2-2'),
	('A man turned into a stone statue','Và rồi một người đàn ông bị biến thành tượng đá','00:00:25.900','00:00:29.800','4000-essential-english-words-2-2'),
	('The people submitted and brought food','Người dân đã nộp và mang tới thức ăn','00:00:29.800','00:00:32.800','4000-essential-english-words-2-2'),
	('The dragon ate all of it and left','Con rồng ngấu nghiến hết số đồ ăn và và rời đi','00:00:32.800','00:00:35.800','4000-essential-english-words-2-2'),
	('The people sent a boy to ask for help from a wise old man','Người dân đã cử một chàng trai đi cầu xin sự giúp đỡ của một ông lão thông thái','00:00:35.800','00:00:39.800','4000-essential-english-words-2-2'),
	('He resided in a temple','Ông lão cư ngụ trong một ngôi chùa','00:00:39.800','00:00:42.800','4000-essential-english-words-2-2'),
	('The boy told the old man about the dragon','Chàng trai nói với ông lão về chuyện con rồng','00:00:42.800','00:00:45.800','4000-essential-english-words-2-2'),
	('Then, the old man counseled the boy','Sau đó, ông lão đã mách chàng trai rằng','00:00:45.800','00:00:48.800','4000-essential-english-words-2-2'),
	('"A meteor will fall in the northern sky"','"Một ngôi sao băng sẽ rơi trên bầu trời phía Bắc"','00:00:48.800','00:00:52.600','4000-essential-english-words-2-2'),
	('"It will make a huge explosion"','"Nó sẽ tạo ra một vụ nổ lớn"','00:00:52.600','00:00:55.000','4000-essential-english-words-2-2'),
	('"Find the meteor and bring it to me"','"Hãy tìm ngôi sao băng đó và mang về đây cho ta"','00:00:55.000','00:00:58.000','4000-essential-english-words-2-2'),
	('"I will use it to make a sword for you"','"Nó sẽ tạo nên một vụ nổ lớn"','00:00:58.000','00:01:01.000','4000-essential-english-words-2-2'),
	('The boy did as the old man said','Cậu bé làm theo lời ông già nói','00:01:01.000','00:01:04.200','4000-essential-english-words-2-2'),
	('Soon, the sword was ready','Chẳng bao lâu sau, một thanh kiếm','00:01:04.200','00:01:07.000','4000-essential-english-words-2-2'),
	('"Use this to kill the dragon"','"Hãy dùng thanh kiếm này để giết chết con rồng"','00:01:07.000','00:01:10.000','4000-essential-english-words-2-2'),
	('"But be careful"','"Nhưng con phải cẩn thận"','00:01:10.000','00:01:12.000','4000-essential-english-words-2-2'),
	('"You must cover yourself with weeds that smell bad"','"Con phải khoác lên mình một lớp cỏ dại để tạo mùi hương lạ"','00:01:12.000','00:01:15.600','4000-essential-english-words-2-2'),
	('"That will ensure that he does not smell you," the man said','"Điều đó sẽ đảm bảo rằng con rồng không ngửi thấy con," ông lão nói','00:01:15.600','00:01:20.000','4000-essential-english-words-2-2'),
	('The boy traveled for many days to find the castle','Chàng trai đi nhiều ngày trời để tìm kiếm tòa lâu đài','00:01:20.000','00:01:24.000','4000-essential-english-words-2-2'),
	('He went to the upper level and opened a door','Cậu trèo lên tầng cao và mở một cánh cửa ra','00:01:24.000','00:01:27.000','4000-essential-english-words-2-2'),
	('He could see the dragon\'s tail','Tại đây cậu có thể nhìn thấy đuôi của con rồng','00:01:27.000','00:01:29.200','4000-essential-english-words-2-2'),
	('It was sleeping, so the boy killed it','Con rồng đang ngủ nên cậu đã giết được nó','00:01:29.200','00:01:33.000','4000-essential-english-words-2-2'),
	('Then, he took the dragon\'s gold and jewelry and returned to his town','Tiếp đó, cậu lấy vàng và đồ trang sức của con rồng rồi quay trở về ngôi làng của mình','00:01:33.000','00:01:37.300','4000-essential-english-words-2-2'),
	('The people were happy','Từ đó mọi người trong làng sống hạnh phúc, bình yên bên nhau','00:01:37.300','00:01:40.000','4000-essential-english-words-2-2'),

	/* (UUID(),'4000-essential-english-words-2-3','The battle of Thermopylae','Trận chiến Thermopylae','4000_ESSENTIAL_ENGLISH_WORDS_033.mp3',NULL,'00:00:00.000','00:01:41.000','4000-essential-english-words-2',0,0,33) */
	('This is a true story','Đây là một câu chuyện có thật','00:00:03.000','00:00:05.800','4000-essential-english-words-2-3'),
	('It happened long ago in Greece','Nó xảy ra cách đây rất lâu ở Hy Lạp','00:00:05.800','00:00:08.800','4000-essential-english-words-2-3'),
	('"We must fight," the Spartan chief told his small army of brave men','"Chúng ta phải chiến đấu" chỉ huy người Sparta nói với đạo quân nhỏ bé nhưng dũng cảm của ông','00:00:08.800','00:00:14.800','4000-essential-english-words-2-3'),
	('They were at a great disadvantage','Họ đang gặp phải một trở ngại rất lớn','00:00:14.800','00:00:17.400','4000-essential-english-words-2-3'),
	('There were only three hundred of them','Họ chỉ còn lại ba trăm người','00:00:17.400','00:00:20.000','4000-essential-english-words-2-3'),
	('The Persian military had hundreds of thousands of men','Trong khi quân đội Ba Tư lại có hàng trăm ngàn binh lính','00:00:20.000','00:00:24.100','4000-essential-english-words-2-3'),
	('They were going to lose unless they could secure a small entrance','Họ sẽ thua nếu họ không giữ được lối đi nhỏ duy nhất này','00:00:24.100','00:00:29.100','4000-essential-english-words-2-3'),
	('The enemy couldn\'t move through it easily','Lối đi nhỏ đến mức kẻ địch không thể tiến vào một cách dễ dàng','00:00:29.100','00:00:32.100','4000-essential-english-words-2-3'),
	('They intended to stop the enemy here','Họ có ý định ngăn chặn kẻ địch tại đây','00:00:32.100','00:00:35.600','4000-essential-english-words-2-3'),
	('The chief and his men got ready for the battle','Chỉ huy và quân lính của ông đã sẵn sàng cho trận chiến','00:00:35.600','00:00:38.800','4000-essential-english-words-2-3'),
	('Soon, long lines of the enemy\'s army twisted around the hills','Chẳng bao lâu, hàng ngàn quân lính bao vây xung quanh các ngọn đồi','00:00:38.800','00:00:44.100','4000-essential-english-words-2-3'),
	('The chief met the enemy with laughter','Chỉ huy nhìn đám quân địch với giọng cười mỉa mai','00:00:44.100','00:00:47.100','4000-essential-english-words-2-3'),
	('He knew that his men\'s weapons and skills were better','Ông biết rằng vũ khí và kỹ năng đánh trận của đội quân ông tốt hơn','00:00:47.100','00:00:51.100','4000-essential-english-words-2-3'),
	('The Spartans trusted their leader and obeyed him','Quân lính Sparta tin tưởng vào tài lãnh đạo và tuân theo lời của ông','00:00:51.100','00:00:54.800','4000-essential-english-words-2-3'),
	('First, the enemy soldiers shot arrows from their bows','Đầu tiên, quân địch bắn cung','00:00:54.800','00:00:59.400','4000-essential-english-words-2-3'),
	('The chief told his men to lift their shields','Chỉ huy ra lệnh cho đội quân của mình dùng khiên chắn','00:00:59.400','00:01:03.000','4000-essential-english-words-2-3'),
	('The arrows stuck into the shields but did not hurt any of the men','Nhờ vậy mà những mũi tên khi va vào khiên không làm bị thương bất kỳ ai','00:01:03.000','00:01:07.800','4000-essential-english-words-2-3'),
	('Then the enemy\'s soldiers attacked the Spartans with long spears','Tiếp đó quân địch tấn công quân lính Sparta bằng những cây giáo dài','00:01:07.800','00:01:13.200','4000-essential-english-words-2-3'),
	('The chief surprised them','Chỉ huy bất ngờ phản công','00:01:13.200','00:01:15.400','4000-essential-english-words-2-3'),
	('His troops rolled logs down on the enemy','Đó là ông cho đội quân lăn hàng loạt những khúc gỗ xuống quân địc','00:01:15.400','00:01:18.800','4000-essential-english-words-2-3'),
	('They fought for three days','Họ đã chiến đấu ròng rã trong ba ngày trời','00:01:18.800','00:01:21.300','4000-essential-english-words-2-3'),
	('Though they hardly slept at all, the chief and his men remained steady','Mặc dù họ không thể chợp mắt chút nào, nhưng chỉ huy và đoàn quân của ông vẫn giữ được tinh thần vững vàng','00:01:21.300','00:01:26.900','4000-essential-english-words-2-3'),
	('But the enemy found a way to beat the Spartans','Nhưng cuối cùng quân địch đã tìm ra được cách để đánh bại đội quân Sparta','00:01:26.900','00:01:30.900','4000-essential-english-words-2-3'),
	('The chief and all of his men were killed','Chỉ huy và tất cả đoàn quân của ông đã bị giết chết','00:01:30.900','00:01:33.900','4000-essential-english-words-2-3'),
	('Even though they lost, the Battle ofThermopylae is one of the most famous battles in history','Mặc dù họ đã thất bại, nhưng trận đánh Thermopylae đã trở thành một trong những trận đánh nổi tiếng nhất trong lịch sử','00:01:33.900','00:01:41.000','4000-essential-english-words-2-3'),

	/* (UUID(),'4000-essential-english-words-2-4','The deer and his image','Con huơu và hình tượng của nó','4000_ESSENTIAL_ENGLISH_WORDS_034.mp3',NULL,'00:00:00.000','00:01:34.100','4000-essential-english-words-2',0,0,34) */
	('A deer told himself every day, "I am the most handsome deer in the forest"','Có một con hươu ngày ngày ca ngợi với bản thân rằng, "Mình là con hươu đẹp trai nhất trong khu rừng này"','00:00:03.500','00:00:09.900','4000-essential-english-words-2-4'),
	('"My large chest is a symbol of my power"','"Bộ ngực lớn là biểu tượng cho sức mạnh"','00:00:09.900','00:00:13.400','4000-essential-english-words-2-4'),
	('"And my beautiful horns impress other animals"','"Và cặp sừng tuyệt đẹp này luôn gây ấn tượng với những loài vật khác"','00:00:13.400','00:00:16.900','4000-essential-english-words-2-4'),
	('But he did not like his legs and hooves','Nhưng nó lại chẳng thích đôi chân với bộ móng','00:00:16.900','00:00:20.100','4000-essential-english-words-2-4'),
	('"My legs are narrow, and my hooves are ugly"','"Ôi cái chân của mình thật là hẹp còn bộ móng trông lại thật xấu xí"','00:00:20.100','00:00:24.100','4000-essential-english-words-2-4'),
	('"They do not satisfy me"','"Mình không hài lòng về chúng tý nào cả"','00:00:24.100','00:00:26.200','4000-essential-english-words-2-4'),
	('One day, the deer saw a big dog','Một ngày nọ, con hươu trông thấy một con chó to','00:00:26.200','00:00:29.900','4000-essential-english-words-2-4'),
	('The deer made some noise and disturbed the dog','Nó đã gây ra tiếng động và quấy rầy đến con chó','00:00:29.900','00:00:33.000','4000-essential-english-words-2-4'),
	('The dog woke up and chased him','Con chó tỉnh dậy và đuổi theo con hươu','00:00:33.000','00:00:36.000','4000-essential-english-words-2-4'),
	('The deer felt terror','Con hươu cảm thấy khiếp sợ','00:00:36.000','00:00:38.000','4000-essential-english-words-2-4'),
	('He screamed','Nó hét lên','00:00:38.000','00:00:39.400','4000-essential-english-words-2-4'),
	('He did not want to be a victim, so he ran into the forest','Nó chạy thẳng vào rừng vì không muốn trở thành nạn nhân của con chó','00:00:39.400','00:00:44.000','4000-essential-english-words-2-4'),
	('His strong legs helped him run fast','Đôi chân khỏe mạnh đã giúp nó chạy thật nhanh','00:00:44.000','00:00:46.900','4000-essential-english-words-2-4'),
	('His pale brown hooves were hard, so they were not sensitive to rough rocks','Bộ móng màu nâu nhạt cứng cáp, nên chúng không dễ bị thương bởi mấy cái cục đá lởm chởm kia','00:00:46.900','00:00:51.900','4000-essential-english-words-2-4'),
	('However, his horns got caught in branches, slowing him down','Tuy nhiên, cặp sừng của nó lại bị kẹt trong các nhánh cây, làm nó chậm lại','00:00:51.900','00:00:57.100','4000-essential-english-words-2-4'),
	('His large chest could not fit between thick trees','Còn bộ ngực rộng lại chẳng vừa vặn giữa những hàng cây dày rậm','00:00:57.100','00:01:01.000','4000-essential-english-words-2-4'),
	('The deer estimated that he ran for an hour','Con hươu ước tính nó đã chạy được khoảng chừng một giờ đồng hồ','00:01:01.000','00:01:04.100','4000-essential-english-words-2-4'),
	('He felt like he was running a marathon','Nó cảm thấy như đang chạy marathon','00:01:04.100','00:01:07.000','4000-essential-english-words-2-4'),
	('In the end, the deer escaped the threat of the dog','Cuối cùng, con hươu đã thoát khỏi sự đe dọa của con chó','00:01:07.000','00:01:11.000','4000-essential-english-words-2-4'),
	('He sat in the shade of a tree','Nó ngồi phịch dưới bóng cây','00:01:11.000','00:01:13.200','4000-essential-english-words-2-4'),
	('"That was almost a disaster"','"Thật đúng là một thảm họa"','00:01:13.200','00:01:16.000','4000-essential-english-words-2-4'),
	('"I almost did not escape because of my chest and horns"','"Mình gần như không thể trốn thoát được bởi bộ ngực và cặp sừng này"','00:01:16.000','00:01:20.000','4000-essential-english-words-2-4'),
	('"My legs and hooves saved me"','"May sao đôi chân và bộ móng này đã cứu mình"','00:01:20.000','00:01:23.000','4000-essential-english-words-2-4'),
	('As a consequence, the deer learned to honor his fast legs and have confidence in his strong hooves','Kết quả là, con hươu đã học được cách tôn trọng đôi chân nhanh nhạy và cảm thấy tự tin với bộ móng chắc khỏe của mình','00:01:23.000','00:01:29.900','4000-essential-english-words-2-4'),
	('"Pretty things only supplement important things," he thought','"Những thứ đẹp đẽ chỉ bổ sung cho những điều quan trọng mà thôi," nó nghĩ','00:01:29.900','00:01:34.100','4000-essential-english-words-2-4'),

	/* (UUID(),'4000-essential-english-words-2-5','May 29,1953','Ngày 29 tháng 5 năm 1953','4000_ESSENTIAL_ENGLISH_WORDS_035.mp3',NULL,'00:00:00.000','00:01:35.200','4000-essential-english-words-2',0,0,35) */
	('Today is the most important day of my life','Hôm nay là ngày vô cùng đặc biệt đối với tôi','00:00:04.800','00:00:08.000','4000-essential-english-words-2-5'),
	('I finally climbed Mt.Everest, the tallest mountain in the world','Cuối cùng thì tôi cũng đã leo lên được Đỉnh Everest, đỉnh núi cao nhất thế giới','00:00:08.000','00:00:13.000','4000-essential-english-words-2-5'),
	('The top of the mountain was amazing','Đứng trên đỉnh núi cảm giác thật tuyệ','00:00:13.000','00:00:15.700','4000-essential-english-words-2-5'),
	('It felt like we were close to heaven','Cái cảm giác như chúng tôi đang đứng rất gần với thiên đường','00:00:15.700','00:00:18.800','4000-essential-english-words-2-5'),
	('The snow was so thick that my boots sank','Tuyết quá dày đến nỗi đôi ủng của tôi bị ngập toàn tuyết với tuyết','00:00:18.800','00:00:22.800','4000-essential-english-words-2-5'),
	('The air was silent','Không khí thật tĩnh lặng','00:00:22.800','00:00:24.800','4000-essential-english-words-2-5'),
	('I looked at the beauty that surrounded me','Quang cảnh xung quanh tôi đẹp lạ kỳ','00:00:24.800','00:00:27.400','4000-essential-english-words-2-5'),
	('Maybe my story will be a legend someday','Có thể một ngày nào đó câu chuyện của tôi sẽ trở thành huyền thoại','00:00:27.400','00:00:30.800','4000-essential-english-words-2-5'),
	('I want people to remember this forever','Tôi muốn mọi người nhớ về nó mãi mãi','00:00:30.800','00:00:34.000','4000-essential-english-words-2-5'),
	('I was the senior explorer in my group, and I knew we needed proof of our climb','Là một nhà thám hiểm lâu năm trong nhóm, tôi biết chúng tôi cần phải có bằng chứng về chuyến leo núi của mình','00:00:34.000','00:00:40.800','4000-essential-english-words-2-5'),
	('I took many pictures with my camera','Tôi đã chụp rất nhiều bức ảnh','00:00:40.800','00:00:43.800','4000-essential-english-words-2-5'),
	('I\'ll put them in a frame and hang them','Tôi bỏ chúng vào khung và treo lên tường','00:00:43.800','00:00:46.000','4000-essential-english-words-2-5'),
	('On the mountain, the air was very cold','Ở trên núi, không khí rất lạnh','00:00:46.000','00:00:49.800','4000-essential-english-words-2-5'),
	('I wrapped my coat around my body','Tôi phải phủ thêm nhiều lớp áo trên người','00:00:49.800','00:00:52.800','4000-essential-english-words-2-5'),
	('I looked over the side of the mountaintop','Tôi nhìn qua sườn núi','00:00:52.800','00:00:55.800','4000-essential-english-words-2-5'),
	('From that angle, I saw the border of the clouds touch the rocks below','Từ góc này có thể nhìn thấy những áng mây chạm vào tảng đá bên dưới','00:00:55.800','00:01:01.800','4000-essential-english-words-2-5'),
	('The snow was thick','Tuyết rất dày','00:01:01.800','00:01:03.300','4000-essential-english-words-2-5'),
	('It looked pure','Gần như trong suốt','00:01:03.300','00:01:04.900','4000-essential-english-words-2-5'),
	('There was no sign of modern life','Không có dấu hiệu của sự sống hiện đại','00:01:04.900','00:01:08.000','4000-essential-english-words-2-5'),
	('Thousands of years ago, my ancestors saw the world this way','Cách đây hàng nghìn năm, tổ tiên của chúng ta đã nhìn thế giới theo cách này','00:01:08.000','00:01:12.000','4000-essential-english-words-2-5'),
	('After fifteen minutes, I knew it was time to proceed down the mountain','Mười lăm phút sau, tôi biết rằng đã đến lúc phải xuống núi','00:01:12.000','00:01:17.500','4000-essential-english-words-2-5'),
	('The whole team congratulated us','Cả đội đã vỗ tay chúc mừng chúng tôi','00:01:17.500','00:01:20.100','4000-essential-english-words-2-5'),
	('My superior, John Hunt, praised us all','Đàn anh của tôi, John Hunt, đã tán dương tất cả chúng tôi','00:01:20.100','00:01:23.400','4000-essential-english-words-2-5'),
	('I sent messages to my relatives to tell them that I was safe','Tôi gửi tin nhắn đến cho người thân của mình để thông báo rằng tôi đã an toàn','00:01:23.400','00:01:28.100','4000-essential-english-words-2-5'),
	('But it was hard to leave the mountain so quickly','Nhưng thật khó để rời khỏi ngọn núi này một cách nhanh chóng','00:01:28.100','00:01:31.200','4000-essential-english-words-2-5'),
	('I wanted to enjoy the incredible sight even longer','Thật sự tôi vẫn muốn được chiêm ngưỡng cảnh sắc tuyệt diệu này lâu hơn','00:01:31.200','00:01:35.200','4000-essential-english-words-2-5');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-2-6','The frog prince','Hoàng tử ếch','4000_ESSENTIAL_ENGLISH_WORDS_036.mp3',NULL,'00:00:00.000','00:01:34.000','4000-essential-english-words-2',0,0,36) */
	('A lovely princess sat by the pool and played with a sculpture of a bear','Một công chúa đáng yêu ngồi bên bể bơi và chơi với bức tượng điêu khắc một con gấu','00:00:03.000','00:00:08.100','4000-essential-english-words-2-6'),
	('Suddenly, she dropped it, and it rolled away','Đột nhiên, cô đánh rơi nó, và nó lăn đi','00:00:08.100','00:00:12.100','4000-essential-english-words-2-6'),
	('She chased it, but it fell into the water','Cô ấy đã đuổi theo nó, nhưng nó đã rơi xuống nước','00:00:12.100','00:00:15.900','4000-essential-english-words-2-6'),
	('She began to cry','Cô bắt đầu khóc','00:00:15.900','00:00:17.900','4000-essential-english-words-2-6'),
	('A large, ugly frog asked, "Why are you crying?"','Một chú ếch to, xấu xí hỏi, "Tại sao bạn khóc?"','00:00:17.900','00:00:22.100','4000-essential-english-words-2-6'),
	('After the princess told him, the frog said, "I can get the sculpture"','Sau khi nàng công chúa kể với chú ếch, chú nói, "Tôi có thể lấy bức tượng điêu khắc"','00:00:22.100','00:00:27.300','4000-essential-english-words-2-6'),
	('"What will you give me in exchange for the favor?"','"Vậy bạn sẽ đưa tôi cái gì thay cho sự trả ơn đây?"','00:00:27.300','00:00:30.900','4000-essential-english-words-2-6'),
	('"I can pay you a fee in gold," she said','"Tôi có thể trả cho bạn phí bằng vàng," cô nói','00:00:30.900','00:00:34.100','4000-essential-english-words-2-6'),
	('But the frog protested','Nhưng chú ếch từ chối','00:00:34.100','00:00:36.100','4000-essential-english-words-2-6'),
	('"I want to sleep in your bed, and you must kiss me in the morning"','"Tôi muốn ngủ trong chiếc giường của bạn, và bạn phải hôn tôi vào buổi sáng"','00:00:36.100','00:00:41.000','4000-essential-english-words-2-6'),
	('"He\'d die without water"','"Chú sẽ chết nếu không có nước"','00:00:41.000','00:00:43.000','4000-essential-english-words-2-6'),
	('"So, I don\'t have to keep my promise," she thought','"Vì vậy, tôi không phải giữ lời hứa," cô nghĩ vậy','00:00:43.000','00:00:47.000','4000-essential-english-words-2-6'),
	('The frog dove for a brief moment and got the sculpture','Chú ếch lặn xuống một khoảnh khắc ngắn và lấy được tượng điêu khắc','00:00:47.000','00:00:51.000','4000-essential-english-words-2-6'),
	('Then the princess ran away with it','Sau đó nàng công chúa chạy đi với nó','00:00:51.000','00:00:53.000','4000-essential-english-words-2-6'),
	('Later, the frog went to the palace','Sau đó, chú ếch đã đi tới cung điện','00:00:53.000','00:00:56.800','4000-essential-english-words-2-6'),
	('The king told her to keep her promise','Nhà vua dặn cô phải giữ lời hứa','00:00:56.800','00:01:00.000','4000-essential-english-words-2-6'),
	('This put the princess in a bad mood','Điều này đặt nàng công chúa trong tâm trạng xấu','00:01:00.000','00:01:02.800','4000-essential-english-words-2-6'),
	('She permitted the frog to sleep on her pillow','Cô cho phép chú ếch ngủ trên chiếc gối của cô','00:01:02.800','00:01:06.000','4000-essential-english-words-2-6'),
	('In the morning, she gave him a kiss','Buổi sáng, cô ấy đã trao nó một nụ hôn','00:01:06.000','00:01:09.000','4000-essential-english-words-2-6'),
	('Suddenly, he turned into a guy','Đột nhiên, nó biến thành một chàng trai','00:01:09.000','00:01:12.000','4000-essential-english-words-2-6'),
	('He said, "I\'m from a kingdom abroad"','Chàng trai nói, "Tôi đến từ một vương quốc xa xôi"','00:01:12.000','00:01:16.000','4000-essential-english-words-2-6'),
	('"In my youth, I angered a tribe of cruel witches, who turned me into a frog"','"Hồi còn trẻ, tôi đã chọc giận một nhóm bộ tộc phù thủy, đã biến tôi thành một chú ếch"','00:01:16.000','00:01:21.900','4000-essential-english-words-2-6'),
	('The princess asked him, "Can I be your bride and stay with you forever?"','Cô công chúa hỏi anh, "Em có thể trở thành cô dâu của anh và ở bên cạnh anh mãi mãi chứ?"','00:01:21.900','00:01:27.500','4000-essential-english-words-2-6'),
	('But the prince said, "No"','Nhưng chàng hoàng tử nói, "Không"','00:01:27.500','00:01:30.000','4000-essential-english-words-2-6'),
	('"You disappointed me"','"Nàng làm ta thất vọng"','00:01:30.000','00:01:31.800','4000-essential-english-words-2-6'),
	('"You didn\'t keep your promise"','"Nàng đã không giữ lời hứa của mình','00:01:31.800','00:01:34.000','4000-essential-english-words-2-6'),

	/* (UUID(),'4000-essential-english-words-2-7','A beautiful bird','Chú chim xinh đẹp','4000_ESSENTIAL_ENGLISH_WORDS_037.mp3',NULL,'00:00:00.000','00:01:44.000','4000-essential-english-words-2',0,0,37) */
	('Dr.Norton\'s occupation was a scholar of biology','Nghề nghiệp của Tiến sĩ Norton là một học giả về sinh học','00:00:03.500','00:00:07.200','4000-essential-english-words-2-7'),
	('He learned about all animals on a daily basis','Hàng ngày, ông nghiên cứu về tất cả các loài động vật','00:00:07.200','00:00:11.000','4000-essential-english-words-2-7'),
	('One day he met a sailor from a colony overseas','Một ngày nọ, ông đã gặp một thủy thủ từ một thuộc địa nước ngoài','00:00:11.000','00:00:15.000','4000-essential-english-words-2-7'),
	('The man told Dr.Norton about a talking bird','Người đàn ông nói với tiến sĩ về một con chim biết nói','00:00:15.000','00:00:18.300','4000-essential-english-words-2-7'),
	('The bird fascinated Dr.Norton, so he told his colleagues about it','Con chim đã thu hút Tiến sĩ, nên ông đã nói với đồng nghiệp của mình về nó','00:00:18.300','00:00:23.900','4000-essential-english-words-2-7'),
	('They debated with him: no one thought a bird could talk','Họ tranh luận với ông: chẳng ai lại nghĩ chim có thể nói được cả','00:00:23.900','00:00:28.100','4000-essential-english-words-2-7'),
	('He tried to persuade them, but they laughed at him','Ông cố gắng thuyết phục họ, tuy nhiên họ lại chỉ cười nhạo ông','00:00:28.100','00:00:31.900','4000-essential-english-words-2-7'),
	('Nevertheless, Dr.Norton believed the bird was real','Tuy nhiên, Tiến sĩ Norton lại tin rằng con chim đấy có thực','00:00:31.900','00:00:35.900','4000-essential-english-words-2-7'),
	('His new mission was to find it','Sứ mệnh mới của ông là phải tìm ra được nó','00:00:35.900','00:00:38.200','4000-essential-english-words-2-7'),
	('He wanted factual proof','Ông muốn có được chứng cớ xác thực','00:00:38.200','00:00:40.800','4000-essential-english-words-2-7'),
	('The next day he departed for the colony','Ngày hôm sau, ông khởi hành đến thuộc địa','00:00:40.800','00:00:43.800','4000-essential-english-words-2-7'),
	('The sailor he had met told him to look for a man named Jai, who would be able to help him in his search','Người thủy thủ mà ông từng gặp bảo ông tìm một người đàn ông tên là Jai, là người có thể sẽ giúp ông trong việc tìm kiếm','00:00:43.800','00:00:51.000','4000-essential-english-words-2-7'),
	('After a month of sailing, Dr.Norton finally reached the colony where he met Jai','Sau một tháng trên biển, cuối cùng Tiến sĩ Norton đã đến thuộc địa nơi ông có thể gặp Jai','00:00:51.000','00:00:57.400','4000-essential-english-words-2-7'),
	('"I can take you to where it lives"','"Tôi có thể đưa ông đến nơi nó sống"','00:00:57.400','00:00:59.700','4000-essential-english-words-2-7'),
	('"It lives by the volcano," Jai said','"Nó sống gần núi lửa," Jai nói','00:00:59.700','00:01:03.000','4000-essential-english-words-2-7'),
	('They left the next day','Ngay ngày sau, họ đã rời đi','00:01:03.000','00:01:04.800','4000-essential-english-words-2-7'),
	('A week later, they arrived at the volcano','Và một tuần sau, họ đã đến khu vực núi lửa','00:01:04.800','00:01:08.100','4000-essential-english-words-2-7'),
	('Every day they walked around and looked for the bird, but they couldn\'t find it','Hàng ngày họ đều dạo quanh đó và tìm kiếm con chim, nhưng họ không thể tìm ra nó','00:01:08.100','00:01:14.000','4000-essential-english-words-2-7'),
	('After one month, Dr.Norton could not find the bird, and this depressed him','Sau một tháng, tiến sĩ Norton không thể tìm thấy chú chim, và điều đó làm ông chán nản','00:01:14.000','00:01:19.900','4000-essential-english-words-2-7'),
	('He decided to go home','Ông quyết định về nhà','00:01:19.900','00:01:22.000','4000-essential-english-words-2-7'),
	('On the route back, he walked past some old ruins','Trên đường trở về, ông đi qua những nơi đổ nát cũ','00:01:22.000','00:01:26.200','4000-essential-english-words-2-7'),
	('He heard someone say, "Hello"','Ông nghe thấy ai đó nói, "Xin chào"','00:01:26.200','00:01:29.000','4000-essential-english-words-2-7'),
	('"Who are you?" he asked','"Ai đó?" ông hỏi','00:01:29.000','00:01:31.300','4000-essential-english-words-2-7'),
	('Dr.Norton looked up and saw a bird','Tiến sĩ Norton dõi mắt tìm kiếm và ông đã trông thấy một con chim','00:01:31.300','00:01:34.900','4000-essential-english-words-2-7'),
	('Dr.Norton put the talking bird into a cage','Tiến sĩ Norton bỏ con chim biết nói vào trong một cái lồng','00:01:34.900','00:01:38.900','4000-essential-english-words-2-7'),
	('Then he returned home','Sau đó ông quay trở về nhà','00:01:38.900','00:01:40.900','4000-essential-english-words-2-7'),
	('He had made a significant discovery','Ông đã có một phát hiện quan trọng','00:01:40.900','00:01:44.000','4000-essential-english-words-2-7'),

	/* (UUID(),'4000-essential-english-words-2-8','Tricky turtle','Chú rùa khôn lanh','4000_ESSENTIAL_ENGLISH_WORDS_038.mp3',NULL,'00:00:00.000','00:01:44.000','4000-essential-english-words-2',0,0,38) */
	('Ricky the rabbit and Tera the turtle met by the edge of the river','Thỏ Ricky và rùa Tera gặp nhau ở bờ sông','00:00:03.000','00:00:08.000','4000-essential-english-words-2-8'),
	('"No one is capable of beating me in a race" Ricky said','"Không ai có khả năng đánh bại tôi trong cuộc đua" Ricky nói','00:00:08.000','00:00:12.900','4000-essential-english-words-2-8'),
	('He was confident, his smile conveyed that','Anh ấy rất tự tin, nụ cười của anh ấy thể hiện điều đó','00:00:12.900','00:00:16.800','4000-essential-english-words-2-8'),
	('"I can beat you," Tera said','"Tôi có thể đánh bại cậu", Tera nói','00:00:16.800','00:00:19.800','4000-essential-english-words-2-8'),
	('Ricky laughed with delight','Ricky bật cười sảng khoái','00:00:19.800','00:00:22.000','4000-essential-english-words-2-8'),
	('Tera said, "We will race tomorrow"','Tera nói, "Ngày mai chúng ta cùng đua"','00:00:22.000','00:00:25.800','4000-essential-english-words-2-8'),
	('"The destination is the hill"','"Đích đến là ngọn đồi"','00:00:25.800','00:00:27.800','4000-essential-english-words-2-8'),
	('Ricky agreed','Ricky đồng ý','00:00:27.800','00:00:29.800','4000-essential-english-words-2-8'),
	('Tera concentrated on winning the race','Tera tập trung để dành chiến thắng trong cuộc đua','00:00:29.800','00:00:32.800','4000-essential-english-words-2-8'),
	('She was not faster than Ricky','Cô rùa không nhanh hơn Ricky','00:00:32.800','00:00:35.000','4000-essential-english-words-2-8'),
	('She needed a definite way to succeed','Nên nó cần một cách thức rõ ràng để thành công','00:00:35.000','00:00:38.600','4000-essential-english-words-2-8'),
	('She told her family about the race, "I have concluded that I have to resort to something bad"','Cô đã nói với gia đình về cuộc đua, "Con đã kết luận rằng con buộc phải dùng một vài thứ xấu xa"','00:00:38.600','00:00:44.800','4000-essential-english-words-2-8'),
	('"I will cheat"','"Con sẽ ăn gian"','00:00:44.800','00:00:46.400','4000-essential-english-words-2-8'),
	('She dictated her instructions to them','Cô nói ra ý định của mình cho họ biết','00:00:46.400','00:00:48.900','4000-essential-english-words-2-8'),
	('At the race, they all wore white feathers','Ở đường đua, tất cả đều khoác lên bộ lông màu trắng','00:00:48.900','00:00:53.000','4000-essential-english-words-2-8'),
	('They looked exactly the same','Nhìn họ hoàn toàn giống nhau','00:00:53.000','00:00:55.000','4000-essential-english-words-2-8'),
	('Then, her family members hid in shadows on the path','Sau đó các thành viên trong gia đình của Tera ẩn trong các bóng râm trên đường đua','00:00:55.000','00:00:59.000','4000-essential-english-words-2-8'),
	('The race began','Cuộc đua bắt đầu','00:00:59.000','00:01:00.900','4000-essential-english-words-2-8'),
	('Tera was soon far behind','Tera nhanh chóng bị bỏ lại đằng sau','00:01:00.900','00:01:03.400','4000-essential-english-words-2-8'),
	('However, Tera\'s brother hid behind a bush in the valley below','Tuy nhiên, em trai Tera đã ẩn nấp đằng sau một bụi cây trong thung lũng bên dưới','00:01:03.400','00:01:08.000','4000-essential-english-words-2-8'),
	('When Ricky got close, Tera\'s brother began to run','Khi Ricky đến gần, em trai Tera bắt đầu chạy','00:01:08.000','00:01:12.000','4000-essential-english-words-2-8'),
	('He looked just like Tera','Cậu ta trông rất giống với Tera','00:01:12.000','00:01:15.000','4000-essential-english-words-2-8'),
	('Ricky ran as fast as he could along the path','Ricky chạy nhanh nhất có thể dọc theo con đường','00:01:15.000','00:01:18.000','4000-essential-english-words-2-8'),
	('But, to him, it seemed like Tera was always ahead','Nhưng, với Ricky, cậu ta luôn cho rằng Tera luôn dẫn đầu','00:01:18.000','00:01:22.000','4000-essential-english-words-2-8'),
	('Ricky had used a considerable amount of energy','Ricky đã tiêu tốn một lượng năng lượng đáng kể','00:01:22.000','00:01:25.800','4000-essential-english-words-2-8'),
	('He reached the top, but Tera\'s sister was already there','Ricky chạy tới đích nhưng chị của Tera đã ở đấy rồi','00:01:25.800','00:01:30.000','4000-essential-english-words-2-8'),
	('"Well, you win," Ricky said','"Ồ, bạn đã thắng," Ricky nói','00:01:30.000','00:01:33.800','4000-essential-english-words-2-8'),
	('Later, Tera had a broad smile on her face','Sau đó, Tera đã cười vang','00:01:33.800','00:01:37.800','4000-essential-english-words-2-8'),
	('Ricky never suspected','Ricky không nghi ngờ điều gì','00:01:37.800','00:01:40.000','4000-essential-english-words-2-8'),
	('He had been tricked by a family of slow turtles','Cậu đã bị lừa bởi một gia đình rùa chậm chạp','00:01:40.000','00:01:44.000','4000-essential-english-words-2-8'),

	/* (UUID(),'4000-essential-english-words-2-9','The tale of Bartelby O\'Boyle','Câu chuyện về Bartelby O\'Boyle','4000_ESSENTIAL_ENGLISH_WORDS_039.mp3',NULL,'00:00:00.000','00:01:44.000','4000-essential-english-words-2',0,0,39) */
	('Long ago, there was a clever man by the name of Bartelby O\'Boyle','Thuở xưa, có một chàng trai rất thông minh tên là Bartelby O’Boyle','00:00:04.000','00:00:09.000','4000-essential-english-words-2-9'),
	('As a boy, he was kept as a slave by the royal family','Khi còn nhỏ, anh làm nô lệ cho một gia đình hoàng gia','00:00:09.000','00:00:13.800','4000-essential-english-words-2-9'),
	('He saw other children play, but he always had to work','Anh thường nhìn những đứa trẻ khác chơi đùa nhưng còn mình thì luôn phải làm việc','00:00:13.800','00:00:18.700','4000-essential-english-words-2-9'),
	('This frustrated him very much','Điều này khiến anh cảm thấy rất chán nản','00:00:18.700','00:00:21.000','4000-essential-english-words-2-9'),
	('But he was not stupid, and he wanted to change things','Nhưng anh không phải là một đứa trẻ ngu ngốc, và anh muốn thay đổi mọi thứ','00:00:21.000','00:00:26.000','4000-essential-english-words-2-9'),
	('Then one day there was a struggle for authority in the kingdom','Một ngày nọ, trong vương quốc nổ ra một cuộc tranh giành quyền lực','00:00:26.000','00:00:30.800','4000-essential-english-words-2-9'),
	('There was a division of the people, and one group fought against another group to see which would govern the kingdom','Đã có sự phân chia trong dân chúng, một nhóm người này chống lại một nhóm người kia để xem bên nào sẽ cai trị được vương quốc','00:00:30.800','00:00:38.200','4000-essential-english-words-2-9'),
	('There was disorder in the kingdom','Vương quốc trở nên hỗn loạn','00:00:38.200','00:00:40.800','4000-essential-english-words-2-9'),
	('Bartelby ran away','Bartelby đã bỏ chạy','00:00:40.800','00:00:42.800','4000-essential-english-words-2-9'),
	('He saw much fighting and destruction','Anh đã chứng kiến rất nhiều cuộc chiến và sự tàn phá','00:00:42.800','00:00:46.400','4000-essential-english-words-2-9'),
	('Many people had nothing to eat','Nhiều người đã chẳng còn gì để ăn','00:00:46.400','00:00:49.000','4000-essential-english-words-2-9'),
	('Bartelby decided to aid them','Bartelby quyết định trợ giúp họ','00:00:49.000','00:00:52.000','4000-essential-english-words-2-9'),
	('He would help them get food','Anh quyết định mang thức ăn đến cho họ','00:00:52.000','00:00:53.900','4000-essential-english-words-2-9'),
	('But how?','Nhưng bằng cách nào?','00:00:53.900','00:00:55.800','4000-essential-english-words-2-9'),
	('Bartelby went to the capital to find an answer','Bartelby bèn đi đến thủ đô để tìm kiếm câu trả lời','00:00:55.800','00:00:59.100','4000-essential-english-words-2-9'),
	('There, he met a man named Gilliam','Tại đây, anh đã gặp một người đàn ông tên là Gilliam','00:00:59.100','00:01:02.800','4000-essential-english-words-2-9'),
	('A group of men attempted to hurt Gilliam','Và một nhóm người đang ra sức làm Gilliam bị thương','00:01:02.800','00:01:06.200','4000-essential-english-words-2-9'),
	('Bartelby defended him','Bartelby đã bảo vệ anh ta','00:01:06.200','00:01:08.500','4000-essential-english-words-2-9'),
	('Then, he gave Gilliam some food to relieve his hunger','Sau đó, anh đưa cho Gilliam một ít thức ăn để làm dịu đi cơn đói của ông','00:01:08.500','00:01:12.400','4000-essential-english-words-2-9'),
	('After that, the two became friends','Và sau đó, hai người trở thành bạn bè','00:01:12.400','00:01:15.600','4000-essential-english-words-2-9'),
	('They took food from the rich and gave it to the poor','Họ lấy thức ăn của người giàu chia cho người nghèo','00:01:15.600','00:01:19.700','4000-essential-english-words-2-9'),
	('Soon, other people cooperated with them','Không lâu sau đó, đã có nhiều người cùng tham gia','00:01:19.700','00:01:22.900','4000-essential-english-words-2-9'),
	('Working together enabled them to take more food','Cùng nhau làm việc giúp họ lấy thêm được nhiều thức ăn hơn','00:01:22.900','00:01:26.900','4000-essential-english-words-2-9'),
	('But they only took food from people who had plenty, and they always gave it to those who had none','Nhưng họ chỉ lấy thức ăn từ những người có rất nhiều thức ăn rồi chuyển nó cho những người không có','00:01:26.900','00:01:34.000','4000-essential-english-words-2-9'),
	('Because of this, Bartleby gained a reputation across the kingdom','Vì những điều này, danh tiếng của Bartelby vang khắp vương quốc','00:01:34.000','00:01:38.800','4000-essential-english-words-2-9'),
	('Even today, many people admire him for helping the poor','Thậm chí đến bây giờ, nhiều người vẫn ngưỡng mộ anh về câu chuyện giúp đỡ những người nghèo khổ','00:01:38.800','00:01:44.000','4000-essential-english-words-2-9'),

	/* (UUID(),'4000-essential-english-words-2-10','Blackbeard','Râu đen','4000_ESSENTIAL_ENGLISH_WORDS_040.mp3',NULL,'00:00:00.000','00:01:36.700','4000-essential-english-words-2',0,0,40) */
	('A longtime ago, I had my first job','Cách đây rất lâu rồi, tôi đã tìm được công việc đầu tiên của mình','00:00:03.000','00:00:06.900','4000-essential-english-words-2-10'),
	('It didn\'t give me much of an income','Nó không mang lại cho tôi nhiều thu nhập','00:00:06.900','00:00:09.000','4000-essential-english-words-2-10'),
	('It was on a giant pirate ship','Đó là công việc trên một con tàu cướp biển khổng lồ','00:00:09.000','00:00:12.000','4000-essential-english-words-2-10'),
	('On my first night, there was a thick fog over the water','Vào đêm đầu tiên, màn sương mù dày đặc bao phủ trên mặt nước biển','00:00:12.000','00:00:16.000','4000-essential-english-words-2-10'),
	('A lamp on the ship revealed an enormous man','Ngọn đèn trên tàu đã làm lộ ra một người đàn ông to lớn','00:00:16.000','00:00:19.800','4000-essential-english-words-2-10'),
	('He had a sword in his belt','Ông ta có một thanh gươm ở thắt lưng','00:00:19.800','00:00:22.400','4000-essential-english-words-2-10'),
	('His name was Blackbeard, and he was one of the most violent pirates ever','Tên ông ta là Râu Đen, và là một trong những tên cướp biển tàn bạo nhất từ trước tới giờ','00:00:22.400','00:00:28.400','4000-essential-english-words-2-10'),
	('One day, Blackbeard did an extraordinary thing','Rồi một ngày, Râu Đen đã làm một điều thật phi thường','00:00:28.400','00:00:32.800','4000-essential-english-words-2-10'),
	('He attacked several ships near a town','Ông ta tấn công một số con thuyền ở gần một thị trấn','00:00:32.800','00:00:35.200','4000-essential-english-words-2-10'),
	('He took some of the town\'s citizens','Ông đã bắt một vài người dân của thị trấn','00:00:35.200','00:00:38.200','4000-essential-english-words-2-10'),
	('Then he declared, "You give me medicine"','Sau đó ông ta tuyên bố, "Các ngươi hãy đưa thuốc cho ta"','00:00:38.200','00:00:42.000','4000-essential-english-words-2-10'),
	('Blackbeard wanted the medicine for some of the sick pirates on his ship','Râu Đen muốn lấy thuốc để chữa bệnh cho một số tên cướp biển đang bị ốm trên con tàu của ông ta','00:00:42.000','00:00:47.000','4000-essential-english-words-2-10'),
	('The people had a bad impression of him','Mọi người đều có ấn tượng xấu về ông','00:00:47.000','00:00:50.000','4000-essential-english-words-2-10'),
	('They were mad, and they resisted','Họ đã nổi giận và họ kháng cự lại','00:00:50.000','00:00:53.000','4000-essential-english-words-2-10'),
	('But they were trapped','Nhưng rồi họ đều bị bắt giữ lại','00:00:53.000','00:00:55.200','4000-essential-english-words-2-10'),
	('They wanted to get rid of him','Họ muốn tống khứ ông ta','00:00:55.200','00:00:57.800','4000-essential-english-words-2-10'),
	('So the town\'s council decided to give him the medicine','Thế là hội đồng thị trấn đã quyết định đưa thuốc cho ông ta','00:00:57.800','00:01:01.000','4000-essential-english-words-2-10'),
	('After this, there was a reward for catching Blackbeard','Sau đó, người ta đã treo thưởng cho ai bắt được Râu Đen','00:01:01.000','00:01:05.200','4000-essential-english-words-2-10'),
	('If Blackbeard was caught, he would have a trial','Nếu Râu Đen bị bắt, ông ta sẽ bị xét xử','00:01:05.200','00:01:08.900','4000-essential-english-words-2-10'),
	('He didn\'t want to go to jail, so he quit being a pirate','Vì không muốn ngồi tù, nên Râu Đen đã từ bỏ làm cướp biển','00:01:08.900','00:01:13.200','4000-essential-english-words-2-10'),
	('Blackbeard became a fisherman','Râu Đen trở thành một người đánh cá','00:01:13.200','00:01:15.700','4000-essential-english-words-2-10'),
	('But he ought to have stayed on land','Nhưng lẽ ra ông ta nên ở lại trên đất liền','00:01:15.700','00:01:18.200','4000-essential-english-words-2-10'),
	('The Royal Navy was still looking for him','Hải quân Hoàng gia vẫn đang truy tìm ông ta','00:01:18.200','00:01:21.000','4000-essential-english-words-2-10'),
	('They attacked him while he was fishing on his boat','Họ tấn công ông khi ông đang đánh cá trên thuyền','00:01:21.000','00:01:24.600','4000-essential-english-words-2-10'),
	('Blackbeard fought against many men','Râu Đen đã đánh lại rất nhiều người khác','00:01:24.600','00:01:27.700','4000-essential-english-words-2-10'),
	('Finally, he was killed','Nhưng cuối cùng thì ông đã bị giết','00:01:27.700','00:01:30.000','4000-essential-english-words-2-10'),
	('He didn\'t even get a funeral','Ông ta thậm chí còn không được tổ chức đám tang','00:01:30.000','00:01:32.600','4000-essential-english-words-2-10'),
	('But people still tell tales about him many years later','Nhưng nhiều người vẫn kể chuyện về ông trong rất nhiều năm sau đó','00:01:32.600','00:01:36.700','4000-essential-english-words-2-10');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-2-11','Dinosaur drawings','Bức hình khủng long','4000_ESSENTIAL_ENGLISH_WORDS_041.mp3',NULL,'00:00:00.000','00:01:39.200','4000-essential-english-words-2',0,0,41) */
	('It was the worst morning ever','Đó là một buổi sáng tồi tệ nhất từ trước tới giờ','00:00:03.000','00:00:05.800','4000-essential-english-words-2-11'),
	('When Carl woke up, he realized that he didn\'t do his astronomy and chemistry homework','Khi tỉnh dậy, Carl nhận ra anh ấy đã không làm bài tập về nhà môn thiên văn học và hóa học','00:00:05.800','00:00:12.200','4000-essential-english-words-2-11'),
	('Also, the forecast called for rain and that would affect baseball practice','Hơn thế nữa, dự báo nói rằng trời hôm nay sẽ mưa và điều đó sẽ ảnh hưởng đến giờ thực hành bóng chày','00:00:12.200','00:00:18.200','4000-essential-english-words-2-11'),
	('Suddenly, his mother yelled, "Take out the garbage right now"','Bỗng nhiên, mẹ anh ấy gọi toáng lên, "Đi đổ rác ngay lập tức"','00:00:18.200','00:00:23.000','4000-essential-english-words-2-11'),
	('When Carl returned from taking the garbage outside, he was all wet','Khi Carl quay về từ điểm đổ rác, anh ấy bị ướt cả người','00:00:23.000','00:00:28.100','4000-essential-english-words-2-11'),
	('"What a terrible day," he said','"Thật là một ngày tồi tệ" anh ấy nói ','00:00:28.100','00:00:31.100','4000-essential-english-words-2-11'),
	('He walked to class','Anh ấy đi bộ đến lớp','00:00:31.100','00:00:33.000','4000-essential-english-words-2-11'),
	('He put his umbrella on the shelf and sat in the third row','Anh đặt ô lên kệ và ngồi xuống dãy bàn thứ ba','00:00:33.000','00:00:37.600','4000-essential-english-words-2-11'),
	('But the teacher asked why Carl\'s umbrella was on the floor','Nhưng cô giáo hỏi tại sao ô của Carl lại nằm trên sàn nhà','00:00:37.600','00:00:41.400','4000-essential-english-words-2-11'),
	('He told her not to blame him','Anh ấy nói với cô giáo đó không phải do anh ấy làm','00:00:41.400','00:00:43.600','4000-essential-english-words-2-11'),
	('But she sent him to the principal out of spite','Nhưng cô giáo đã cho anh đến gặp thầy hiệu trưởng','00:00:43.600','00:00:47.200','4000-essential-english-words-2-11'),
	('Next, he took a geography test','Tiếp đó, anh ấy phải làm bài kiểm tra môn địa','00:00:47.200','00:00:50.200','4000-essential-english-words-2-11'),
	('Despite studying, Carl didn\'t know the answers','Mặc dù đã học bài, nhưng Carl không thể biết câu trả lời','00:00:50.200','00:00:54.000','4000-essential-english-words-2-11'),
	('He started drawing lightly on his paper','Anh ta bắt đầu vẽ bừa lên tờ giấy','00:00:54.000','00:00:57.000','4000-essential-english-words-2-11'),
	('Carl drew a huge dinosaur','Anh ấy vẽ một con khủng long khổng lồ','00:00:57.000','00:01:00.000','4000-essential-english-words-2-11'),
	('What if it were real?','Liệu nó có thật thì sao nhỉ?','00:01:00.000','00:01:01.800','4000-essential-english-words-2-11'),
	('He saw it in his mind','Anh ấy nghĩ thầm','00:01:01.800','00:01:04.000','4000-essential-english-words-2-11'),
	('Carl\'s class said he was a genius for having a dinosaur','Các bạn cùng lớp nói rằng Anh ta là một thiên tài vì có một con khủng long to như thế','00:01:04.000','00:01:08.200','4000-essential-english-words-2-11'),
	('It could interfere with math class, too','Điều này có thể ảnh hưởng đến cả giờ toán nữa','00:01:08.200','00:01:11.800','4000-essential-english-words-2-11'),
	('Soon, Carl\'s fame spread through school','Không lâu sau, danh tiếng của Carl lan rộng khắp trường','00:01:11.800','00:01:15.600','4000-essential-english-words-2-11'),
	('He taught his dinosaur to be very gentle and put it on exhibit','Anh ấy thuần hóa con khủng long của mình trở nên hiền lành và đưa ra triển lãm','00:01:15.600','00:01:20.900','4000-essential-english-words-2-11'),
	('But admission would only be given to those classmates who paid him a fee','Nhưng vá vào cửa sẽ chỉ dành cho những người bạn cùng lớp, những người có trả phí cho anh ấy','00:01:20.900','00:01:26.000','4000-essential-english-words-2-11'),
	('His idea was super','Ý tưởng của anh ấy thật tuyệt vời','00:01:26.000','00:01:28.100','4000-essential-english-words-2-11'),
	('"It\'s time to turn in your tests," the teacher said','"Đã đến giờ nộp bài" giáo viên nói','00:01:28.100','00:01:32.300','4000-essential-english-words-2-11'),
	('Carl looked at his paper','Carl nhìn vào bài thi của anh ấy','00:01:32.300','00:01:34.300','4000-essential-english-words-2-11'),
	('As he was dreaming in class, he hadn\'t finished the test','Khi mà anh ấy đang mơ trong lớp thì bài kiểm tra đã không được hoàn thành','00:01:34.300','00:01:39.200','4000-essential-english-words-2-11'),

	/* (UUID(),'4000-essential-english-words-2-12','The mean chef','Đầu bếp xấu tính','4000_ESSENTIAL_ENGLISH_WORDS_042.mp3',NULL,'00:00:00.000','00:01:29.500','4000-essential-english-words-2',0,0,42) */
	('Once there was a chef, who was mean to his cooks','Ngày xưa có một người bếp trưởng, ông luôn đối xử tệ với các đầu bếp của mình','00:00:03.400','00:00:07.400','4000-essential-english-words-2-12'),
	('He was mean to the people who came in to eat','Ông rất khó tính đối với những người tới đây ăn uống','00:00:07.400','00:00:10.800','4000-essential-english-words-2-12'),
	('He charged too much for meals','Ông thu phí các món ăn rất cao','00:00:10.800','00:00:13.000','4000-essential-english-words-2-12'),
	('Many people were not able to afford the cheapest bean dish','Nhiều người không có khả năng mua món đậu rẻ nhất','00:00:13.000','00:00:16.800','4000-essential-english-words-2-12'),
	('When his metal oven broke, he did not have it fixed','Khi lò vi sóng bằng kim loại bị hỏng, ông không sửa lại nó','00:00:16.800','00:00:21.000','4000-essential-english-words-2-12'),
	('So everything baked in it burned','Nên mọi thứ nướng trong đó đều bị cháy đen','00:00:21.000','00:00:23.800','4000-essential-english-words-2-12'),
	('The only light was from candles, and the whole place was a mess','Ánh sáng duy nhất là từ ngọn nến, và toàn bộ không gian trở thành một mớ hỗn độn','00:00:23.800','00:00:28.400','4000-essential-english-words-2-12'),
	('Sometimes, he didn\'t pay his waiters','Thỉnh thoảng, ông không trả tiền cho phục vụ','00:00:28.400','00:00:31.100','4000-essential-english-words-2-12'),
	('Since they had no funds, they had many debts','Từ đó họ không có thu nhập, họ đã mắc nợ quá nhiều','00:00:31.100','00:00:34.900','4000-essential-english-words-2-12'),
	('The chef behaved this way all the time','Người bếp trưởng lúc nào cũng đối xử với mọi người theo cách này','00:00:34.900','00:00:37.900','4000-essential-english-words-2-12'),
	('He monitored the cooks and yelled if they did not do things his way','Ông quản lý các đầu bếp và la mắng họ nếu họ không làm theo ý ông','00:00:37.900','00:00:42.000','4000-essential-english-words-2-12'),
	('One day, the cooks decided that they were tired of the abuse and that they would not be passive anymore','Một ngày, họ quyết định rằng họ mệt mỏi với sự lạm quyền này và họ không còn muốn bị động nữa','00:00:42.000','00:00:49.200','4000-essential-english-words-2-12'),
	('Everyone opposed the chef','Mọi người đều đứng lên chống lại người bếp trưởng','00:00:49.200','00:00:52.000','4000-essential-english-words-2-12'),
	('At first, they thought about suing him','Lúc đầu, họ nghĩ sẽ kiện ông ta','00:00:52.000','00:00:55.000','4000-essential-english-words-2-12'),
	('Instead, they tied up the chef with rope','Nhưng thay vào đó, họ trói ông ta bằng sợi dây thừng','00:00:55.000','00:00:58.400','4000-essential-english-words-2-12'),
	('Now, they controlled the restaurant','Bây giờ họ đã có thể kiểm soát nhà hàng','00:00:58.400','00:01:01.000','4000-essential-english-words-2-12'),
	('They decreased the price of food','Họ giảm giá thức ăn','00:01:01.000','00:01:04.000','4000-essential-english-words-2-12'),
	('They used the best ingredients and made large quantities of food','Họ sử dụng những nguyên liệu tốt nhất và làm ra một số lượng lớn thức ăn','00:01:04.000','00:01:08.000','4000-essential-english-words-2-12'),
	('They turned on the lights','Họ bật hết đèn lên','00:01:08.000','00:01:10.000','4000-essential-english-words-2-12'),
	('The restaurant was converted into a happy place','Nhà hàng thay đổi thành một nơi hạnh phúc, ấm áp','00:01:10.000','00:01:13.400','4000-essential-english-words-2-12'),
	('For the first time, many people came to eat','Vì thế, lần đầu tiên có rất nhiều người đến đây ăn uống','00:01:13.400','00:01:17.000','4000-essential-english-words-2-12'),
	('The chef realized that the restaurant\'s problems were his fault','Người bếp trưởng đã nhận ra vấn đề của nhà hàng là do lỗi của mình','00:01:17.000','00:01:21.000','4000-essential-english-words-2-12'),
	('The chef learned an important lesson','Ông đã học được một bài học quan trọng','00:01:21.000','00:01:24.000','4000-essential-english-words-2-12'),
	('The new, generous chef insisted on giving the customers a free meal','Người bếp trưởng mới kiên quyết cho khách một bữa ăn miễn phí','00:01:24.000','00:01:29.500','4000-essential-english-words-2-12'),

	/* (UUID(),'4000-essential-english-words-2-13','The Cat and the Fox','Mèo và Cáo','4000_ESSENTIAL_ENGLISH_WORDS_043.mp3',NULL,'00:00:00.000','00:01:37.000','4000-essential-english-words-2',0,0,43) */
	('One day, a cat hiked on a mountain','Một ngày nọ, một con mèo leo lên một ngọn núi','00:00:03.800','00:00:06.700','4000-essential-english-words-2-13'),
	('When he reached the peak, he met a fox','Khi nó tới đỉnh núi, nó đã gặp một con cáo','00:00:06.700','00:00:09.800','4000-essential-english-words-2-13'),
	('They began talking about how they get away from their enemies','Chúng bắt đầu nói cho nhau nghe về cách để tránh được kẻ thù của mình','00:00:09.800','00:00:13.800','4000-essential-english-words-2-13'),
	('"I am very smart"','"Tôi rất thông minh"','00:00:13.800','00:00:16.000','4000-essential-english-words-2-13'),
	('"I have billions of ideas"','"Tôi có vô vàn ý tưởng"','00:00:16.000','00:00:18.800','4000-essential-english-words-2-13'),
	('"I can carve a tiny hole in a tree, and then climb in," the fox said','" Tôi có thể khoét được một lỗ rất nhỏ trên thân cây và chui vào trong đó," cáo nói','00:00:18.800','00:00:25.000','4000-essential-english-words-2-13'),
	('He added, "I have a lot of friends"','Cáo nói thêm, "Tôi có rất nhiều bạn bè"','00:00:25.000','00:00:28.300','4000-essential-english-words-2-13'),
	('"If I am in trouble, I can call them to lend their help"','"Nếu tôi gặp rắc rối, tôi có thể nhờ sự trợ giúp từ họ"','00:00:28.300','00:00:32.400','4000-essential-english-words-2-13'),
	('"I can escape an entire army if I have to"','"Tôi có thể thoát khỏi kẻ thù nếu gặp phải chúng"','00:00:32.400','00:00:36.000','4000-essential-english-words-2-13'),
	('Then, the fox asked, "What are your potential plans?"','Sau đó, Cáo hỏi, "Kế hoạch tiềm năng của cậu là gì?"','00:00:36.000','00:00:40.500','4000-essential-english-words-2-13'),
	('The cat said, "I have only one plan"','Mèo trả lời, "Tôi chỉ có một kế hoạch"','00:00:40.500','00:00:44.200','4000-essential-english-words-2-13'),
	('The fox said, "I hope you have good fortune, then"','Cáo nói, "Tôi hi vọng bạn gặp may mắn"','00:00:44.200','00:00:48.700','4000-essential-english-words-2-13'),
	('"Do you want me to be your tutor?"','"Bạn có muốn tôi làm người hướng dẫn cho bạn không?"','00:00:48.700','00:00:51.000','4000-essential-english-words-2-13'),
	('"I can teach you many things"','"Tôi có thể dạy bạn mọi thứ"','00:00:51.000','00:00:54.000','4000-essential-english-words-2-13'),
	('The cat said, "I guarantee that my plan works every time"','Mèo nói, "Tôi đảm bảo rằng kế hoạch của tôi có thể hoạt động bất kỳ lúc nào"','00:00:54.000','00:00:59.000','4000-essential-english-words-2-13'),
	('"We can quit talking about it"','"Chúng ta có thể dừng cuộc nói chuyện về vấn đề này ở đây rồi"','00:00:59.000','00:01:01.800','4000-essential-english-words-2-13'),
	('Soon, they saw a group of wolves','Chẳng bao lâu, họ nhìn thấy một đàn sói','00:01:01.800','00:01:04.800','4000-essential-english-words-2-13'),
	('It was an emergency','Đó là một tình huống khẩn cấp','00:01:04.800','00:01:06.800','4000-essential-english-words-2-13'),
	('The cat quickly used her plan','Mèo nhanh chóng thực hiện kế hoạch của mình','00:01:06.800','00:01:09.300','4000-essential-english-words-2-13'),
	('She ran up a tree','Nó trèo lên một cái cây','00:01:09.300','00:01:11.300','4000-essential-english-words-2-13'),
	('The fox could not decide which plan to use','Cáo thì không thể quyết định nên sử dụng kế hoạch nào','00:01:11.300','00:01:15.000','4000-essential-english-words-2-13'),
	('"What should my initial move be?"','"Kế hoạch ban đầu của mình nên là gì nhỉ?"','00:01:15.000','00:01:17.300','4000-essential-english-words-2-13'),
	('"Should I consult my friends?"','"Mình có nên tham khảo ý kiến của các bạn không?"','00:01:17.300','00:01:19.500','4000-essential-english-words-2-13'),
	('The fox felt intense anxiety','Cáo cảm thấy vô cùng lo lắng','00:01:19.500','00:01:22.700','4000-essential-english-words-2-13'),
	('All he could do was spin in a circle','Mọi điều nó có thể làm là xoay thành một vòng tròn','00:01:22.700','00:01:25.600','4000-essential-english-words-2-13'),
	('The wolves caught the fox','Những con sói đã bắt được cáo','00:01:25.600','00:01:28.100','4000-essential-english-words-2-13'),
	('The cat was full of pride','Mèo thì đầy tự hào','00:01:28.100','00:01:30.400','4000-essential-english-words-2-13'),
	('This is proof that having a good plan is better than having many bad plans','Đây là bằng chứng cho thấy có một kế hoạch hay thì tốt hơn là có nhiều kế hoạch không ra gì','00:01:30.400','00:01:37.000','4000-essential-english-words-2-13'),

	/* (UUID(),'4000-essential-english-words-2-14','The Good Student','Học sinh giỏi','4000_ESSENTIAL_ENGLISH_WORDS_044.mp3',NULL,'00:00:00.000','00:01:38.000','4000-essential-english-words-2',0,0,44) */
	('Sue left her dormitory early that morning','Sue rời kí túc xá từ sáng sớm','00:00:03.000','00:00:06.000','4000-essential-english-words-2-14'),
	('She had even washed her uniform the night before','Cô thậm chí đã giặt đồng phục của mình từ đêm hôm trước','00:00:06.000','00:00:09.800','4000-essential-english-words-2-14'),
	('She wanted to look nice for the day','Cô muốn trông mình thật xinh đẹp trong ngày hôm nay','00:00:09.800','00:00:12.100','4000-essential-english-words-2-14'),
	('Sue was committed to learning, and she had a talent for getting good grades','Sue đã cam kết là sẽ học tập, và cô đã có một tài năng trong việc giành được điểm cao','00:00:12.100','00:00:18.000','4000-essential-english-words-2-14'),
	('In fact, Sue didn\'t sleep much','Thực tế, Sue đã không được ngủ nhiều','00:00:18.000','00:00:21.000','4000-essential-english-words-2-14'),
	('She composed a paper and found the perfect thesis about the importance of greenhouses','Cô đã soạn bài ra một tờ giấy và tìm ra luận điểm hoàn hảo về tầm quan trọng của nhà kính','00:00:21.000','00:00:26.800','4000-essential-english-words-2-14'),
	('She also studied for her physics test','Cô cũng ôn tập cho bài kiểm tra môn vật lý','00:00:26.800','00:00:29.700','4000-essential-english-words-2-14'),
	('Sue was already tired','Sue thực sự đã rất mệt','00:00:29.700','00:00:32.000','4000-essential-english-words-2-14'),
	('During the test, she calculated her answers','Trong quá trình kiểm tra, cô đã tính toán các câu trả lời của mình','00:00:32.000','00:00:35.800','4000-essential-english-words-2-14'),
	('Soon, she felt sick','Tuy nhiên, cô bị ốm','00:00:35.800','00:00:38.600','4000-essential-english-words-2-14'),
	('Her face got hot, and her vision began to blur','Mặt cô trở nên nóng bừng và tầm nhìn thì bắt đầu mờ dần','00:00:38.600','00:00:43.000','4000-essential-english-words-2-14'),
	('She was blind for a moment','Cô bắt đầu không nhìn thấy gì trong giây lát','00:00:43.000','00:00:45.200','4000-essential-english-words-2-14'),
	('The teacher saw Sue\'s apparent sickness','Thầy giáo đã nhìn thấy được bệnh tình rõ rệt của Sue','00:00:45.200','00:00:48.200','4000-essential-english-words-2-14'),
	('He wanted to send her to the nurse','Ông muốn đưa cô đến gặp y tá','00:00:48.200','00:00:51.000','4000-essential-english-words-2-14'),
	('But she wouldn\'t go','Thế nhưng Sue lại không muốn đi','00:00:51.000','00:00:52.800','4000-essential-english-words-2-14'),
	('Sue still had a portion of the test to finish','Sue vẫn còn một phần của bài kiểm tra phải hoàn thành','00:00:52.800','00:00:56.000','4000-essential-english-words-2-14'),
	('After that, Sue went to the nurse','Sau đó, Sue đã đi gặp y tá','00:00:56.000','00:00:59.000','4000-essential-english-words-2-14'),
	('After seeing the secretary, she waited','Sau khi nhìn thấy người trợ lý, cô đã ngồi đợi','00:00:59.000','00:01:02.100','4000-essential-english-words-2-14'),
	('A few minutes later, the nurse came in with a glass of juice and told Sue they needed to chat','Một vài phút sau đó, y tá mang đến một cốc nước hoa quả trong tay và bảo Sue rằng họ cần nói chuyện một chút','00:01:02.100','00:01:08.800','4000-essential-english-words-2-14'),
	('"It is obvious that you have exhausted yourself," the nurse said','"Rõ ràng là bản thân cháu đã bị kiệt sức", y tá nói','00:01:08.800','00:01:13.800','4000-essential-english-words-2-14'),
	('"If you keep working so hard, it could have severe results"','"Nếu cháu cứ tiếp tục học tập quá độ thế này, sẽ gây ra hậu quả nghiêm trọng"','00:01:13.800','00:01:18.100','4000-essential-english-words-2-14'),
	('"My parents tell me that all the time"','"Cha mẹ cháu luôn nói với cháu như vậy"','00:01:18.100','00:01:21.000','4000-essential-english-words-2-14'),
	('"I guess I shouldn\'t ignore them," Sue said','"Có lẽ là cháu không nên phớt lờ đi lời khuyên của họ", Sue nói','00:01:21.000','00:01:24.000','4000-essential-english-words-2-14'),
	('"You have to remind yourself it is OK to rest," the nurse said','"Cháu cần phải luôn nhắc nhở bản thân rằng nghỉ ngơi là điều tốt," y tá nói','00:01:24.000','00:01:29.600','4000-essential-english-words-2-14'),
	('When Sue got back to her room, she went right to bed','Khi Sue trở về phòng mình, cô đã đi ngủ ngay','00:01:29.600','00:01:33.600','4000-essential-english-words-2-14'),
	('She made sure she got enough rest every night after that','Cô chắc chắn mình sau này sẽ phải luôn nghỉ ngơi đầy đủ vào mọi buổi tối','00:01:33.600','00:01:38.000','4000-essential-english-words-2-14'),

	/* (UUID(),'4000-essential-english-words-2-15','The Lucky Knife','Con dao may mắn','4000_ESSENTIAL_ENGLISH_WORDS_045.mp3',NULL,'00:00:00.000','00:01:33.000','4000-essential-english-words-2',0,0,45) */
	('I\'ve devoted my life to studying past generations','Tôi đã dành cả cuộc đời tôi để nghiên cứu về các thế hệ trước đây','00:00:03.000','00:00:07.200','4000-essential-english-words-2-15'),
	('Last year, I had a unique chance to work with my uncle','Năm ngoái, tôi có một cơ hội đặc biệt làm việc cùng với chú tôi','00:00:07.200','00:00:11.500','4000-essential-english-words-2-15'),
	('Our job was to find old treasures for a school\'s history foundation','Công việc của chúng tôi là tìm kiếm các kho báu cho một tổ chức nghiên cứu về lịch sử tại một trường học','00:00:11.500','00:00:16.700','4000-essential-english-words-2-15'),
	('He also hired a crew of students','Ông cũng thuê một nhóm sinh viên làm việc cùng nữa','00:00:16.700','00:00:19.700','4000-essential-english-words-2-15'),
	('They signed a contract to work with him','Họ ký hợp đồng làm việc với ông','00:00:19.700','00:00:22.100','4000-essential-english-words-2-15'),
	('He was the boss','Chú tôi là hiệu trưởng','00:00:22.100','00:00:24.000','4000-essential-english-words-2-15'),
	('The place was strange, though','Nơi này cũng thật là lạ','00:00:24.000','00:00:26.000','4000-essential-english-words-2-15'),
	('I dined on many things that I had never tasted before','Tôi đã ăn rất nhiều thứ mà tôi chưa bao giờ thử trước đây','00:00:26.000','00:00:30.200','4000-essential-english-words-2-15'),
	('They had an unusual flavor','Chúng có hương vị thật kỳ lạ','00:00:30.200','00:00:32.800','4000-essential-english-words-2-15'),
	('We had been there about a month and hadn\'t found anything','Chúng tôi đã ở đó trong khoảng một tháng và rốt cục chả tìm thấy gì cả','00:00:32.800','00:00:36.800','4000-essential-english-words-2-15'),
	('One day, I began to dig in the soil','Một ngày, tôi bắt đầu đào đất','00:00:36.800','00:00:40.700','4000-essential-english-words-2-15'),
	('The ground\'s layers got wetter','Những lớp đất nền trở nên ẩm ướt hơn','00:00:40.700','00:00:43.000','4000-essential-english-words-2-15'),
	('Soon I was digging in the mud','Một lúc sau tôi đào thấy bùn','00:00:43.000','00:00:45.300','4000-essential-english-words-2-15'),
	('My shovel began to get very heavy','Xẻng của tôi đã bắt đầu nặng hơn','00:00:45.300','00:00:48.500','4000-essential-english-words-2-15'),
	('It felt like it had doubled in weight because the ground had absorbed a lot of water','Tôi có cảm giác như trọng lượng của nó đã tăng lên gấp đôi bởi mặt đất đã hấp thụ rất nhiều nước','00:00:48.500','00:00:54.000','4000-essential-english-words-2-15'),
	('Finally, I saw something in the mud','Cuối cùng, tôi tìm thấy thứ gì đó trong đống bùn','00:00:54.000','00:00:56.800','4000-essential-english-words-2-15'),
	('It was an old knife','Nó là một con dao cũ','00:00:56.800','00:00:59.000','4000-essential-english-words-2-15'),
	('The handle felt smooth in my hand','Cán dao nhẵn mịn ở trong tay','00:00:59.000','00:01:02.000','4000-essential-english-words-2-15'),
	('I elevated it so I could see it better','Tôi đã giơ nó lên để có thể quan sát kỹ hơn','00:01:02.000','00:01:05.000','4000-essential-english-words-2-15'),
	('There was writing on it','Có dòng chữ gì đó viết trên dao','00:01:05.000','00:01:06.800','4000-essential-english-words-2-15'),
	('"It says it will bring good luck," my uncle said with a smile','"Nó sẽ mang lại may mắn cho chủ nhân," chú tôi cười và nói với tôi','00:01:06.800','00:01:11.000','4000-essential-english-words-2-15'),
	('"Why don\'t you keep it?"','"Sao con không giữ nó luôn nhỉ?"','00:01:11.000','00:01:12.800','4000-essential-english-words-2-15'),
	('I put it in my tent','"Tôi bỏ con dao lại vào trong lều"','00:01:12.800','00:01:14.800','4000-essential-english-words-2-15'),
	('The next day, we found many more things','Hôm sau, chúng tôi lại tiếp tục tìm thấy nhiều thứ hơn','00:01:14.800','00:01:18.500','4000-essential-english-words-2-15'),
	('There were pots, jewelry and weapons','Trong số đồ vật đó có nồi niêu, trang sức và vũ khí','00:01:18.500','00:01:22.000','4000-essential-english-words-2-15'),
	('My uncle donated all of the things to a special committee','Chú tôi đã quyên góp tất cả mọi thứ cho một ủy ban đặc biệt','00:01:22.000','00:01:26.000','4000-essential-english-words-2-15'),
	('Many newspapers wrote stories about it','Rất nhiều tờ báo đã viết những câu chuyện về thành tích của chúng tôi','00:01:26.000','00:01:29.000','4000-essential-english-words-2-15'),
	('It seemed the knife really did bring good luck','Dường như con dao đó thực sự đã mang lại may mắn cho chúng tôi','00:01:29.000','00:01:33.000','4000-essential-english-words-2-15');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-2-16','Prince Sam','Hoàng tử Sam','4000_ESSENTIAL_ENGLISH_WORDS_046.mp3',NULL,'00:00:00.000','00:01:50.200','4000-essential-english-words-2',0,0,46) */
	('Sam\'s mother cooked at the royal palace','Mẹ của Sam nấu ăn trong một cung điện hoàng gia','00:00:03.000','00:00:06.000','4000-essential-english-words-2-16'),
	('One day, he went to work with her','Một ngày nọ, cậu bé đi làm cùng mẹ','00:00:06.000','00:00:08.800','4000-essential-english-words-2-16'),
	('She emphasized that he should stay in the kitchen','Bà đã nhấn mạnh rằng cậu chỉ nên ở yên trong bếp','00:00:08.800','00:00:12.000','4000-essential-english-words-2-16'),
	('But Sam was bored','Nhưng Sam cảm thấy chán ngắt','00:00:12.000','00:00:14.000','4000-essential-english-words-2-16'),
	('Thus, he decided to look around','Thế là, cậu quyết định nhìn ngó xung quanh','00:00:14.000','00:00:17.000','4000-essential-english-words-2-16'),
	('He went around a corner','Cậu bé đi vòng quanh góc tường','00:00:17.000','00:00:19.200','4000-essential-english-words-2-16'),
	('It shocked him to see a boy who had a strong likeness to him','Cậu đã bị sốc khi nhìn thấy một cậu bé khác có bề ngoài giống mình như tạc','00:00:19.200','00:00:23.200','4000-essential-english-words-2-16'),
	('Sam soon recovered','Sam nhanh chóng bình tĩnh lại','00:00:23.200','00:00:25.000','4000-essential-english-words-2-16'),
	('The other boy stared at him','Cậu bé kia nhìn chằm chằm vào Sam','00:00:25.000','00:00:27.400','4000-essential-english-words-2-16'),
	('Then he spoke "Come with me"','Sau đó cậu cất lời "Đi theo mình"','00:00:27.400','00:00:31.000','4000-essential-english-words-2-16'),
	('He needed to be rational','Sam cần phải lý trí','00:00:31.000','00:00:32.800','4000-essential-english-words-2-16'),
	('But he couldn\'t deny that he wanted to go','Nhưng cậu không thể phủ nhận rằng mình cũng muốn đi cùng','00:00:32.800','00:00:35.800','4000-essential-english-words-2-16'),
	('So he followed the boy to a chamber','Vậy là cậu bé đi theo người bạn mới tiến đến một phòng ngủ','00:00:35.800','00:00:38.600','4000-essential-english-words-2-16'),
	('"I am Prince Bertram," the boy said','"Mình là hoàng tử Bertram," cậu bạn nói','00:00:38.600','00:00:42.000','4000-essential-english-words-2-16'),
	('Sam felt shy talking to a prince','Sam cảm thấy xấu hổ khi nói chuyện cùng hoàng tử','00:00:42.000','00:00:45.300','4000-essential-english-words-2-16'),
	('"I\'m Sam"','"Mình là Sam"','00:00:45.300','00:00:47.300','4000-essential-english-words-2-16'),
	('"Trade places with me" The prince said','"Hãy trao đổi thân phận với mình đi," Hoàng tử nói','00:00:47.300','00:00:51.000','4000-essential-english-words-2-16'),
	('"We can\'t"','"Không được"','00:00:51.000','00:00:52.100','4000-essential-english-words-2-16'),
	('"My mother will kill me"','"Mẹ mình sẽ giết mình mất"','00:00:52.100','00:00:53.900','4000-essential-english-words-2-16'),
	('"Moreover, I don\'t know anything about being a prince"','"Hơn nữa, mình chẳng biết bất cứ điều gì khi trở thành hoàng tử"','00:00:53.900','00:00:58.000','4000-essential-english-words-2-16'),
	('"No one will find out," the prince interrupted','"Sẽ không có ai phát hiện ra đâu," Hoàng tử ngắt lời','00:00:58.000','00:01:02.000','4000-essential-english-words-2-16'),
	('"We look the same, and even our gestures are the same"','"Chúng ta nhìn giống nhau như một, và thậm chí cả những cử chỉ của chúng ta cũng tương đồn"','00:01:02.000','00:01:06.000','4000-essential-english-words-2-16'),
	('"It will only last for a week"','"Mọi việc sẽ chỉ kéo dài trong một tuần thôi"','00:01:06.000','00:01:09.000','4000-essential-english-words-2-16'),
	('Sam said OK','Sam đồng ý','00:01:09.000','00:01:11.000','4000-essential-english-words-2-16'),
	('Soon, Sam\'s perspective on being a prince changed','Ngay tức khắc, ý nghĩ của Sam về việc trở thành hoàng tử đã thay đổi','00:01:11.000','00:01:15.200','4000-essential-english-words-2-16'),
	('He spent most of his day signing royal documents','Cậu dành phần lớn thời gian trong ngày để ký những tài liệu hoàng gia','00:01:15.200','00:01:19.000','4000-essential-english-words-2-16'),
	('At night, the prince\'s chamber was cold','Khi đêm xuống, phòng ngủ của hoàng tử trở nên lạnh lẽo','00:01:19.000','00:01:22.000','4000-essential-english-words-2-16'),
	('He thought he was going to freeze or get sick with a fever or the flu','Cậu nghĩ cậu sắp bị đóng băng hoặc ốm sốt hoặc là cảm cúm','00:01:22.000','00:01:26.700','4000-essential-english-words-2-16'),
	('He was happy when the week ended','Khi một tuần trôi qua cậu thấy hạnh phúc vô ngần','00:01:26.700','00:01:28.800','4000-essential-english-words-2-16'),
	('So was the prince','Và hoàng tử cũng vậy','00:01:28.800','00:01:31.000','4000-essential-english-words-2-16'),
	('"I didn\'t know how to do anything," the prince said','"Mình chẳng biết làm gì cả," Hoàng tử nói','00:01:31.000','00:01:34.400','4000-essential-english-words-2-16'),
	('"I\'ve always relied on my servants to do everything for me"','"Mình luôn luôn phải dựa vào những người phò tá để họ làm hết mọi việc cho mình"','00:01:34.400','00:01:38.100','4000-essential-english-words-2-16'),
	('"I think I like being a regular person," Sam said','"Mình nghĩ mình thích hợp làm người bình thường," Sam nói','00:01:38.100','00:01:42.100','4000-essential-english-words-2-16'),
	('"Being a prince isn\'t fun"','"Làm hoàng tử không vui một chút nào"','00:01:42.100','00:01:44.500','4000-essential-english-words-2-16'),
	('So, they both returned to their normal positions and enjoyed their lives more than before','Thế là họ đều quay trở về thân phận ban đầu của mình và yêu thích cuộc sống này hơn bao giờ hết','00:01:44.500','00:01:50.200','4000-essential-english-words-2-16'),

	/* (UUID(),'4000-essential-english-words-2-17','Henry Ford\'s Famous Car','Chiếc xe hơi nổi tiếng của Henry Ford','4000_ESSENTIAL_ENGLISH_WORDS_047.mp3',NULL,'00:00:00.000','00:01:31.800','4000-essential-english-words-2',0,0,47) */
	('My name is Henry Ford, and I invented a car called the Model T','Tên tôi là Henry Ford, và tôi đã chế tạo ra một chiếc xe hơi có tên gọi là mô hình T','00:00:03.800','00:00:08.300','4000-essential-english-words-2-17'),
	('I used to watch carriages on the streets','Tôi từng quan sát những chiếc xe ngựa trên đường phố','00:00:08.300','00:00:11.300','4000-essential-english-words-2-17'),
	('They fascinated me','Chúng đã mê hoặc tôi','00:00:11.300','00:00:12.900','4000-essential-english-words-2-17'),
	('Then I got a job as a junior mechanic','Rồi tôi kiếm được việc làm với tư cách là một thợ cơ khí tập sự','00:00:12.900','00:00:15.900','4000-essential-english-words-2-17'),
	('My father criticized me','Cha tôi chỉ trích tôi','00:00:15.900','00:00:17.900','4000-essential-english-words-2-17'),
	('He wanted me to run the farm','Ông muốn tôi điều hành hoạt động của trang trại','00:00:17.900','00:00:19.900','4000-essential-english-words-2-17'),
	('But I did not shift my plans','Nhưng tôi đã không thay đổi kế hoạch của mình','00:00:19.900','00:00:22.100','4000-essential-english-words-2-17'),
	('Then I worked for the Detroit Auto Company','Sau đó tôi đã làm việc cho công ty ô tô Detroit','00:00:22.100','00:00:25.200','4000-essential-english-words-2-17'),
	('But I wanted to make cars using less labor','Nhưng tôi muốn chế tạo ra những chiếc xe hơi sử dụng ít nhân công hơn','00:00:25.100','00:00:28.800','4000-essential-english-words-2-17'),
	('That way, there would be fewer expenses','Bằng cách đó sẽ tiêu tốn ít chi phí hơn','00:00:28.800','00:00:31.800','4000-essential-english-words-2-17'),
	('I started the Ford Motor Company in 1903','Tôi bắt đầu gây dựng công ty Ford Motor vào năm 1903','00:00:31.800','00:00:35.100','4000-essential-english-words-2-17'),
	('At first, the company did not do well','Những ngày đầu tiên, công ty hoạt động không hiệu quả','00:00:35.100','00:00:38.500','4000-essential-english-words-2-17'),
	('But many people were betting on my success','Nhưng có rất nhiều người đã đánh cược vào thành công của tôi','00:00:38.500','00:00:41.800','4000-essential-english-words-2-17'),
	('I also had a sincere aim to make a car that anybody could buy','Tôi cũng có một mục đích chân thành đó là tạo ra một chiếc ô tô mà bất kì ai đều có thể mua','00:00:41.800','00:00:46.400','4000-essential-english-words-2-17'),
	('Then, in 1908,1 introduced the Model-T in a formal ceremony','Sau đó, vào năm 1908, tôi đã giới thiệu chiếc Mô hình-T trong một buổi lễ','00:00:46.400','00:00:51.500','4000-essential-english-words-2-17'),
	('It confirmed that I was right: it was possible to build a car my way','Việc làm này chứng thực rằng tôi đã đúng đắn: Hoàn toàn có thể tạo lên một chiếc xe theo cách của riêng mình','00:00:51.500','00:00:57.000','4000-essential-english-words-2-17'),
	('The Model T differed from other vehicles','Chiếc mô hình T khác biệt so với những loại phương tiện khác','00:00:57.000','00:01:00.000','4000-essential-english-words-2-17'),
	('Workers could attach different parts for cars or trucks','Người lao động có thể gắn những bộ phận khác nhau cho xe hơi hoặc xe tải','00:01:00.000','00:01:04.000','4000-essential-english-words-2-17'),
	('This saved time','Điều này tiết kiệm thời gian','00:01:04.000','00:01:06.000','4000-essential-english-words-2-17'),
	('One Model T could be put together in 93 minutes','Một chiếc mô hình T có thể đươc lắp ráp các bộ phận khác nhau trong vòng 93 phút','00:01:06.000','00:01:10.000','4000-essential-english-words-2-17'),
	('All of them had the same classic design','Tất cả các bộ phận đó đều có chung thiết kế cổ điển','00:01:10.000','00:01:13.000','4000-essential-english-words-2-17'),
	('They were all the same size and height','Chúng cũng có cùng kích cỡ và chiều cao','00:01:13.000','00:01:15.600','4000-essential-english-words-2-17'),
	('The prime reason for doing this was to save money','Nguyên nhân căn bản để làm điều này là tiết kiệm tiền','00:01:15.600','00:01:19.000','4000-essential-english-words-2-17'),
	('Over 19 years, I sold over 15 million Model Ts','Hơn 19 năm qua, tôi đã bán trên 15 triệu chiếc mô hình T','00:01:19.000','00:01:24.000','4000-essential-english-words-2-17'),
	('This sent a signal to other companies','Con số này đã gửi một tín hiệu đến các công ty khác','00:01:24.000','00:01:27.000','4000-essential-english-words-2-17'),
	('People would buy cars to commute to work if the price was low enough','Người dân sẽ mua xe để đi làm đều đặn mỗi ngày nếu giá cả thấp và vừa đủ','00:01:27.000','00:01:31.800','4000-essential-english-words-2-17'),

	/* (UUID(),'4000-essential-english-words-2-18','The Priest','Vị linh mục','4000_ESSENTIAL_ENGLISH_WORDS_048.mp3',NULL,'00:00:00.000','00:01:25.200','4000-essential-english-words-2',0,0,48) */
	('A young priest was always sad','Một vị linh mục trẻ luôn thấy buồn','00:00:03.000','00:00:06.000','4000-essential-english-words-2-18'),
	('He was good at his profession, but he still had no joy','Ông giỏi về chuyên môn của mình, nhưng ông vẫn không chút vui vẻ gì','00:00:06.000','00:00:10.200','4000-essential-english-words-2-18'),
	('He visited a group of wise monks','Ông đã tới thăm một nhóm các thầy tu thông thái','00:00:10.200','00:00:13.000','4000-essential-english-words-2-18'),
	('When he got to the monks\' house, they greeted him and let him in','Khi ông tới ngôi nhà của các thầy tu, họ chào đón ông và để ông ở đó','00:00:13.000','00:00:17.000','4000-essential-english-words-2-18'),
	('The monks asked the priest, "What is the matter?"','Các thầy tu đã hỏi vị linh mục "Có vấn đề gì vậy?"','00:00:17.000','00:00:20.800','4000-essential-english-words-2-18'),
	('The priest said, "I should be happy, but I am not"','Vị linh mục nói "Tôi nên vui vẻ, nhưng tôi không hề gì"','00:00:20.800','00:00:25.400','4000-essential-english-words-2-18'),
	('"I don\'t know what to do"','"Tôi không biết phải làm gì"','00:00:25.400','00:00:27.500','4000-essential-english-words-2-18'),
	('The wise monks paused for a minute','Các thầy tu thông thái đã dừng lại một phút','00:00:27.500','00:00:30.200','4000-essential-english-words-2-18'),
	('Then one said, "We are convinced of your faith"','Rồi một người đã nói, "Chúng tôi được thuyết phục về sự nổi tiếng của ông"','00:00:30.200','00:00:34.000','4000-essential-english-words-2-18'),
	('"You are a very good priest"','"Ông là một vị linh mục rất tốt"','00:00:34.000','00:00:36.000','4000-essential-english-words-2-18'),
	('"But to find joy, you have to do more"','"Nhưng để tìm được niềm vui, ông phải làm hơn nữa"','00:00:36.000','00:00:39.000','4000-essential-english-words-2-18'),
	('"Above all, investigate the elements of your life that you love"','"Hơn hết là, hãy đi điều tra các yếu tố của cuộc sống mà ông yêu quý ấy"','00:00:39.000','00:00:43.800','4000-essential-english-words-2-18'),
	('The priest thought that this answer was odd, but he was curious','Vị linh mục đã nghĩ câu trả lời này thật kỳ quặc, nhưng ông đã tò mò','00:00:43.800','00:00:48.300','4000-essential-english-words-2-18'),
	('The next day, the priest thought about his abilities','Ngày tiếp theo, vị linh mục đã nghĩ về các khả năng của mình','00:00:48.300','00:00:51.700','4000-essential-english-words-2-18'),
	('He got a few ideas, and he did not want to delay any longer','Ông đã có một vài ý tưởng, và ông không muốn trì hoãn thêm nữa','00:00:51.700','00:00:55.800','4000-essential-english-words-2-18'),
	('He liked to draw, so he made some cartoons','Ông thích vẽ, vì vậy ông đã làm một vài hoạt hình','00:00:55.800','00:00:59.200','4000-essential-english-words-2-18'),
	('He also liked to write, so he started a diary','Ông cũng thích viết, vì vậy ông bắt đầu viết nhật ký','00:00:59.200','00:01:03.000','4000-essential-english-words-2-18'),
	('He was interested in agriculture, so he planted some grains','Ông có hứng thú với nông nghiệp, nên ông bắt đầu trồng cây','00:01:03.000','00:01:07.800','4000-essential-english-words-2-18'),
	('He made jam from berries','Ông làm mứt từ dâu','00:01:07.800','00:01:09.900','4000-essential-english-words-2-18'),
	('He made his own labels to put on the jars of jam','Ông đã tạo nhãn hiệu cho riêng mình để đặt lên các lọ mứt','00:01:09.900','00:01:13.400','4000-essential-english-words-2-18'),
	('He painted his ceiling','Ông đã vẽ trần nhà','00:01:13.400','00:01:15.200','4000-essential-english-words-2-18'),
	('The priest learned something','Vị linh mục đã học được điều gì đó','00:01:15.200','00:01:17.400','4000-essential-english-words-2-18'),
	('It is not too hard to be happy after all','Cũng không quá khó để vui vẻ sau tất cả','00:01:17.400','00:01:20.600','4000-essential-english-words-2-18'),
	('All one has to do is find things they like doing, and do them','Mọi thứ bạn phải làm là tìm những thứ họ thích làm và làm chúng','00:01:20.600','00:01:25.200','4000-essential-english-words-2-18'),

	/* (UUID(),'4000-essential-english-words-2-19','Mrs.May and the Green Girl','Bà May và cô bé màu xanh','4000_ESSENTIAL_ENGLISH_WORDS_049.mp3',NULL,'00:00:00.000','00:01:34.200','4000-essential-english-words-2',0,0,49) */
	('One morning, people from a small town found a little girl by a stream','Một buổi sáng nọ, người dân trong một thị trấn tìm thấy một cô gái nhỏ bên cạnh dòng suối','00:00:03.800','00:00:09.000','4000-essential-english-words-2-19'),
	('She seemed to be wearing a green costume','Cô bé dường như đang mặc một bộ đồ có kiểu dáng rất lạ màu xanh lá cây','00:00:09.00','00:00:12.400','4000-essential-english-words-2-19'),
	('As the people got closer, they saw that the girl\'s skin was green','Khi mọi người tiến lại gần cô, họ mới biết rằng da của cô cũng có màu xanh lá cây','00:00:12.400','00:00:17.600','4000-essential-english-words-2-19'),
	('"Oh my," the people exclaimed','"Ôi trời ơi," một ai đó la lên','00:00:17.600','00:00:20.400','4000-essential-english-words-2-19'),
	('"What if her motive for coming to our town is bad?"','"Chuyện gì sẽ xảy ra với thị trấn của chúng ta nếu cô bé này mang chỉ mang đến toàn điều xấu mà thôi?"','00:00:20.400','00:00:24.000','4000-essential-english-words-2-19'),
	('"What if she has a strange origin?"','"Nhỡ đâu nó có năng lực gì đó là lạ thì sao?"','00:00:24.000','00:00:27.000','4000-essential-english-words-2-19'),
	('An old woman kindly went to her','Một người phụ nữ lớn tuổi ân cần đến bên cô bé','00:00:27.000','00:00:29.800','4000-essential-english-words-2-19'),
	('"Look how scared she is"','"Nó sợ các người lắm đấy"','00:00:29.800','00:00:31.900','4000-essential-english-words-2-19'),
	('"Please," she begged','"Làm ơn", bà cầu xin','00:00:31.900','00:00:33.900','4000-essential-english-words-2-19'),
	('"Do not reject her"','"Đừng hắt hủi nó"','00:00:33.900','00:00:35.500','4000-essential-english-words-2-19'),
	('"I will adopt her"','"Tôi sẽ nuôi nó"','00:00:35.500','00:00:37.000','4000-essential-english-words-2-19'),
	('There was silence until the judge spoke','Không khí im lặng cho đến khi vị thẩm phán cất tiếng','00:00:37.000','00:00:40.000','4000-essential-english-words-2-19'),
	('"I don\'t know," he said in a worried tone','"Tôi không biết," ông nói cùng sự lo lắng','00:00:40.000','00:00:43.300','4000-essential-english-words-2-19'),
	('"But we cannot forbid you"','"Nhưng chúng tôi không thể ngăn cấm được bà làm việc đó"','00:00:43.300','00:00:45.400','4000-essential-english-words-2-19'),
	('"I indeed hope you\'re not being a fool"','"Tôi thực lòng hy vọng rằng bà không bị mất trí đấy"','00:00:45.400','00:00:48.700','4000-essential-english-words-2-19'),
	('Mrs.May extended her hand to the girl','Bà May dang rộng vòng tay đón cô né về phía mình','00:00:48.700','00:00:51.800','4000-essential-english-words-2-19'),
	('"Come with me"','"Đến đây với ta nào"','00:00:51.800','00:00:53.000','4000-essential-english-words-2-19'),
	('"I won\'t hurt you"','"Ta sẽ không làm hại gì con đâu"','00:00:53.000','00:00:54.400','4000-essential-english-words-2-19'),
	('The girl spoke a language Mrs.May didn\'t know','Cô bé nói một thứ tiếng gì đó mà bà May không thể hiểu được','00:00:54.400','00:00:57.900','4000-essential-english-words-2-19'),
	('But she was able to interpret what the girl was trying to say','Nhưng bà vẫn cố gắng tìm cách hiểu được những gì mà cô bé đang cố gắng nhắc đến','00:00:57.900','00:01:02.000','4000-essential-english-words-2-19'),
	('Sometimes the girl drew pictures to illustrate what she meant','Đôi khi, cô bé vẽ những bức tranh để thể hiện cho ý định của cô','00:01:02.000','00:01:06.800','4000-essential-english-words-2-19'),
	('The green girl was from a place far beyond the sun','Cô bé da xanh đến từ một một nơi bên ngoài hệ mặt trời','00:01:06.800','00:01:10.700','4000-essential-english-words-2-19'),
	('There, people lived in nests built in trees','Tại đó, mọi người sống trong những chiếc tổ được xây dựng trên cây','00:01:10.700','00:01:14.600','4000-essential-english-words-2-19'),
	('They only ate green leaves, which made their skin green','Những người dân vùng này chỉ ăn lá cây,và điều này sẽ khiến da họ có màu xanh nhiều hơn','00:01:14.600','00:01:18.800','4000-essential-english-words-2-19'),
	('"Well, you can\'t just eat leaves," Mrs.May said','"Chà, cháu không cần ăn lá cây nữa nhé," Bà May nói','00:01:18.800','00:01:23.100','4000-essential-english-words-2-19'),
	('She fed the green girl home-cooked meals, and soon the girl wasn\'t green anymore','Bà ấy nấu những món ăn mà bà thường nấu trong những bữa ăn hàng ngày, và cô gái không còn màu xanh nữa','00:01:23.100','00:01:29.100','4000-essential-english-words-2-19'),
	('The people had a huge reception to welcome her as a citizen of the town','Người dân đã có một sự đón nhận to lớn để chào mừng cô bé như một công dân của thị trấn','00:01:29.100','00:01:34.200','4000-essential-english-words-2-19'),

	/* (UUID(),'4000-essential-english-words-2-20','Albert Einstein','Albert Einstein','4000_ESSENTIAL_ENGLISH_WORDS_050.mp3',NULL,'00:00:00.000','00:01:36.500','4000-essential-english-words-2',0,0,50) */
	('My name is Albert Einstein','Tên tôi là Albert Einstein','00:00:03.000','00:00:05.800','4000-essential-english-words-2-20'),
	('Many people know about the great things I\'ve accomplished','Nhiều người biết về những thứ vĩ đại mà tôi đã đạt được','00:00:05.800','00:00:09.800','4000-essential-english-words-2-20'),
	('But I had many barriers before I became famous','Nhưng không biết tôi đã phải đối mặt với nhiều khó khăn trước khi trở nên nổi tiếng','00:00:09.800','00:00:13.300','4000-essential-english-words-2-20'),
	('I was born in Germany','Tôi được sinh ra ở Đức','00:00:13.300','00:00:15.300','4000-essential-english-words-2-20'),
	('When I was in elementary school, I already knew about math and statistics','Khi tôi đang học tiểu học, tôi đã bắt đầu hiểu biết về Toán và số liệu','00:00:15.300','00:00:20.800','4000-essential-english-words-2-20'),
	('When I was a boy, I pretended to be a great scientist','Khi tôi còn là một cậu nhóc, tôi giả vờ là một nhà khoa học vĩ đại','00:00:20.800','00:00:25.000','4000-essential-english-words-2-20'),
	('I loved school, but my life at home was hard','Tôi yêu trường, nhưng đời sống ở nhà thì lại khó khăn','00:00:25.000','00:00:28.800','4000-essential-english-words-2-20'),
	('My father lost his job, so my family lived in poverty','Cha tôi mất việc, nên gia đình tôi đã phải sống trong nghèo đói','00:00:28.800','00:00:33.200','4000-essential-english-words-2-20'),
	('We could not pay the rent in Germany','Chúng tôi không thể chi trả tiền thuê nhà ở Đức','00:00:33.200','00:00:36.000','4000-essential-english-words-2-20'),
	('We became immigrants and went to Italy','Sau đó, chúng tôi trở thành dân nhập cư và chuyển đến Ý','00:00:36.000','00:00:39.200','4000-essential-english-words-2-20'),
	('I finished high school and went to college in Switzerland','Tôi hoàn thành cấp 3 và bước vào đại học ở Thụy Sĩ','00:00:39.200','00:00:43.000','4000-essential-english-words-2-20'),
	('After college, I began writing about science','Sau đại học, tôi bắt đầu viết về khoa học','00:00:43.000','00:00:47.200','4000-essential-english-words-2-20'),
	('I did not reach success in an instant, though','Mặc dù thế, tôi đã không đạt được thành công ngay lập tức','00:00:47.200','00:00:50.200','4000-essential-english-words-2-20'),
	('At first, other scientists did not approve of my work','Lúc đầu, các nhà khoa học khác không chấp thuận công trình của tôi','00:00:50.200','00:00:54.800','4000-essential-english-words-2-20'),
	('They thought I was a failure','Họ nghĩ rằng tôi là một kẻ thất bại','00:00:54.800','00:00:57.000','4000-essential-english-words-2-20'),
	('Rising to the rank of an admired scientist was a gradual process','Vươn lên đến vị trí của một nhà khoa học được mọi người ngưỡng mộ là một quá trình lâu dài','00:00:57.000','00:01:01.800','4000-essential-english-words-2-20'),
	('Soon, people started to notice that I was right','Không lâu sau, mọi người bắt đầu nhận ra rằng tôi đã đúng','00:01:01.800','00:01:05.500','4000-essential-english-words-2-20'),
	('At last, I began to get some recognition','Cuối cùng, tôi đã bắt đầu có được một vài sự công nhận','00:01:05.500','00:01:09.000','4000-essential-english-words-2-20'),
	('I showed how to find the approximate size of very big things, like stars','Tôi đã chỉ ra cách để tìm ra kích thước xấp xỉ của những thứ rất lớn như các vì sao','00:01:09.000','00:01:14.300','4000-essential-english-words-2-20'),
	('I also detected and explained the movement of very small things, like atoms','Tôi cũng đã phát hiện và giải thích chuyển động của những thứ rất nhỏ như các nguyên tử','00:01:14.300','00:01:20.100','4000-essential-english-words-2-20'),
	('And for fun, I made a machine that could refrigerate food by inserting heat','Và để cho vui, tôi đã làm một chiếc máy có thể giữ lạnh thức ăn bằng cách chèn thêm nhiệt','00:01:20.100','00:01:26.100','4000-essential-english-words-2-20'),
	('I never retired','Tôi chưa bao giờ nghỉ hưu','00:01:26.100','00:01:28.100','4000-essential-english-words-2-20'),
	('It was my duty to keep working','Nghĩa vụ của tôi là tiếp tục làm việc','00:01:28.100','00:01:30.300','4000-essential-english-words-2-20'),
	('I overcame many hard times, and I will be remembered for my important works','Tôi đã vượt qua nhiều lần khó khăn, và tôi tin rằng tôi sẽ được nhớ đến vì những công trình khoa học quan trọng của mình','00:01:30.300','00:01:36.500','4000-essential-english-words-2-20');

/*=====================================================================================================================================================================================================================================================*/

INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-2-21','From the Earth to the Stars','Từ trái đất đến những vì sao','4000_ESSENTIAL_ENGLISH_WORDS_051.mp3',NULL,'00:00:00.000','00:01:41.000','4000-essential-english-words-2',0,0,51) */
	('Jeremy was from a family of miners','Jeremy đến từ một gia đình có truyền thống làm thợ mỏ','00:00:03.800','00:00:06.700','4000-essential-english-words-2-21'),
	('Like them, he worked underground during the day','Giống như những người thợ mỏ khác, anh làm việc dưới lòng đất suốt ngày','00:00:06.700','00:00:10.200','4000-essential-english-words-2-21'),
	('His job was to gather raw minerals and jewels','Công việc của anh là thu thập khoáng sản thô và đá quý','00:00:10.200','00:00:13.800','4000-essential-english-words-2-21'),
	('Each night after work, he lay awake in an open field','Hằng đêm sau khi làm xong công việc, anh ấy nằm thao thức trên một cánh đồng mênh mông','00:00:13.800','00:00:18.100','4000-essential-english-words-2-21'),
	('With his telescope, he looked at the stars','Anh dùng chiếc kính viễn vọng của mình ngắm nhìn những vì sao','00:00:18.100','00:00:21.300','4000-essential-english-words-2-21'),
	('He was amazed by the scale of space','Anh bị choáng ngợp bởi sự bao la của vũ trụ','00:00:21.300','00:00:24.500','4000-essential-english-words-2-21'),
	('He wished someday he might travel there','Anh ước rằng ngày nào đó mình có thể bay vào không gian','00:00:24.500','00:00:28.000','4000-essential-english-words-2-21'),
	('One day there was an accident in the mine','Một ngày nọ, trong mỏ xảy ra một vụ tai nạn','00:00:28.000','00:00:30.800','4000-essential-english-words-2-21'),
	('Water poured into the mine','Nước tràn vào trong mỏ','00:00:30.800','00:00:32.800','4000-essential-english-words-2-21'),
	('Everything was dark','Mọi thứ trở nên tối đen','00:00:32.800','00:00:35.000','4000-essential-english-words-2-21'),
	('Jeremy stretched out and grabbed a piece of wood','Jeremy cố gắng với tới và tóm lấp một mảnh gỗ','00:00:35.000','00:00:38.400','4000-essential-english-words-2-21'),
	('It kept him from sinking','Mảnh gỗ đã giúp anh không bị chìm xuống','00:00:38.400','00:00:40.500','4000-essential-english-words-2-21'),
	('Jeremy felt a presence nearby','Jeremy cảm nhận được có một sự hiện diện nào đó cạnh bên','00:00:40.500','00:00:43.400','4000-essential-english-words-2-21'),
	('"I am an angel," said a voice','"Tôi là thiên thần đây" một giọng nói vang lên','00:00:43.400','00:00:46.000','4000-essential-english-words-2-21'),
	('"What?" Jeremy exclaimed','"Cái gì cơ?" Jeremy kêu lên','00:00:46.000','00:00:48.800','4000-essential-english-words-2-21'),
	('"You must never come underground again"','"Bạn sẽ không bao giờ phải làm việc dưới lòng đất một lần nào nữa"','00:00:48.800','00:00:51.200','4000-essential-english-words-2-21'),
	('"Have the courage to make your wishes come true"','"Hãy can đảm lên để biến những ước mơ của bạn trở thành hiện thực"','00:00:51.200','00:00:55.000','4000-essential-english-words-2-21'),
	('For a long time he floated in silence','Suốt một thời gian dài trôi nổi trong sự yên lặng','00:00:55.000','00:00:58.300','4000-essential-english-words-2-21'),
	('Then he heard other voices','Rồi anh nghe thấy có tiếng nói','00:00:58.300','00:01:01.000','4000-essential-english-words-2-21'),
	('The other miners were coming to rescue him','Thì ra những người thợ mỏ khác đang trên đường đến giải cứu anh','00:01:01.000','00:01:04.000','4000-essential-english-words-2-21'),
	('The next day Jeremy skipped work','Ngày tiếp theo, Jeremy nghỉ làm','00:01:04.000','00:01:07.000','4000-essential-english-words-2-21'),
	('He decided to become an astronaut','Anh quyết định trở thành một phi hành gia','00:01:07.000','00:01:09.300','4000-essential-english-words-2-21'),
	('For the next two years, he studied hard','Trong hai năm sau đó, anh ấy đã học tập chăm chỉ','00:01:09.300','00:01:12.800','4000-essential-english-words-2-21'),
	('One day, he was given permission to participate in a mission to space','Một ngày nọ, anh được phép tham gia vào một nhiệm vụ trong vũ trụ','00:01:12.800','00:01:17.800','4000-essential-english-words-2-21'),
	('His wish had been granted','Điều ước của anh đã thành hiện thực','00:01:17.800','00:01:19.800','4000-essential-english-words-2-21'),
	('His spaceship left the ground','Tàu không gian của anh ấy rời mặt đất','00:01:19.800','00:01:22.100','4000-essential-english-words-2-21'),
	('It went higher until there was no more gravity','Nó bay lên cao cho đến khi không còn bất cứ trọng lực nào nữa','00:01:22.100','00:01:25.400','4000-essential-english-words-2-21'),
	('He saw satellites floating next to the ship','Anh nhìn thấy những vệ tinh trôi nổi bên cạnh con tàu của mình','00:01:25.400','00:01:28.700','4000-essential-english-words-2-21'),
	('Then Jeremy saw a beautiful angel outside his spaceship','Rồi Jeremy nhìn thấy một thiên thần xinh đẹp bên ngoài tàu không gian của anh ấy','00:01:28.700','00:01:32.800','4000-essential-english-words-2-21'),
	('It smiled at Jeremy','Và thiên thần đã mỉm cười với Jeremy','00:01:32.800','00:01:35.200','4000-essential-english-words-2-21'),
	('For some minutes, Jeremy could not speak','Trong vài phút, Jeremy không thể nói nên lời','00:01:35.200','00:01:38.000','4000-essential-english-words-2-21'),
	('Finally, he said, "Thankyou"','Cuối cùng, anh nói, "Cảm ơn"','00:01:38.000','00:01:41.000','4000-essential-english-words-2-21'),

	/* (UUID(),'4000-essential-english-words-2-22','The Farm Festival','Lễ hội nông trại','4000_ESSENTIAL_ENGLISH_WORDS_052.mp3',NULL,'00:00:00.000','00:01:35.800','4000-essential-english-words-2',0,0,52) */
	('Once there was a farm','Ngày xưa, ở một nông trại nọ','00:00:03.000','00:00:05.200','4000-essential-english-words-2-22'),
	('Many animals lived there','Có nhiều con vật cùng nhau sinh sống','00:00:05.200','00:00:07.300','4000-essential-english-words-2-22'),
	('One day, they had a contest in the yard','Một ngày nọ, trong sân tổ chức một cuộc thi','00:00:07.300','00:00:10.800','4000-essential-english-words-2-22'),
	('They were going to race from the barn to the farmer\'s garage','Các con vật sẽ chạy từ chuồng nuôi đến nhà để xe của ông chủ','00:00:10.800','00:00:14.100','4000-essential-english-words-2-22'),
	('The barn and the garage were far apart','Chuồng nuôi và nhà để xe cách xa nhau. Đây sẽ là một cuộc đua đường dài','00:00:14.100','00:00:17.000','4000-essential-english-words-2-22'),
	('It would be a long race','Đây sẽ là một cuộc đua đường dài','00:00:17.000','00:00:19.700','4000-essential-english-words-2-22'),
	('The winner qualified to win a bag full of apples as an award','Người chiến thắng sẽ nhận được một phần thưởng đó là một chiếc túi đầy táo','00:00:19.700','00:00:24.300','4000-essential-english-words-2-22'),
	('But the race did not start well','Nhưng cuộc đua không được thuận lợi','00:00:24.300','00:00:27.300','4000-essential-english-words-2-22'),
	('The cart with all the apples was not stable, and the animals had to repair it','Cái xe đẩy những quả táo không kiên cố nên những con vật phải sửa lại nó','00:00:27.300','00:00:33.000','4000-essential-english-words-2-22'),
	('Then the pup knocked over the apples','Rồi cô cún con làm rơi những quả táo ra ngoài','00:00:33.000','00:00:35.800','4000-essential-english-words-2-22'),
	('The pig yelled, "We are going to slip"','Chú heo hét lên, "Chúng ta sẽ trượt té mất"','00:00:35.800','00:00:38.800','4000-essential-english-words-2-22'),
	('"We must clean up this mess"','"Ta phải dọn dẹp mớ hỗn độn này"','00:00:38.800','00:00:41.000','4000-essential-english-words-2-22'),
	('The pup felt bad, and she began to cry','Cô cún cảm thấy có lỗi, và cô bắt đầu khóc','00:00:41.000','00:00:45.000','4000-essential-english-words-2-22'),
	('The dog gave her a tissue to wipe her tears','Chú chó đưa cô khăn giấy để lau nước mắt','00:00:45.000','00:00:48.300','4000-essential-english-words-2-22'),
	('Then the race resumed','Sau đó cuộc đua được tiếp tục','00:00:48.300','00:00:50.800','4000-essential-english-words-2-22'),
	('But the duck tried to rob them and take all the apples','Nhưng con vịt lại cố gắng cướp và lấy hết tất cả quả táo','00:00:50.800','00:00:54.800','4000-essential-english-words-2-22'),
	('The cat said, "I will have you arrested"','Con mèo nói, "Tôi sẽ bắt bạn"','00:00:54.800','00:00:58.100','4000-essential-english-words-2-22'),
	('The duck said, "You can\'t convict me"','Con vịt nói, "Bạn không thể kết tội tôi"','00:00:58.100','00:01:01.100','4000-essential-english-words-2-22'),
	('"You can\'t prove I took it"','"Bạn không thể chứng minh được tôi lấy nó"','00:01:01.100','00:01:03.100','4000-essential-english-words-2-22'),
	('The race stopped yet again','Cuộc đua dừng lại một lần nữa','00:01:03.100','00:01:05.500','4000-essential-english-words-2-22'),
	('The animals tried to race one more time','Những con vật cố chạy đua một lần nữa','00:01:05.500','00:01:08.400','4000-essential-english-words-2-22'),
	('Then they heard an alarm coming from the barn','Rồi chúng nghe được một tiếng báo đến từ chuồng nuôi','00:01:08.400','00:01:11.200','4000-essential-english-words-2-22'),
	('There was a fire','Có một đám cháy lớn','00:01:11.200','00:01:13.400','4000-essential-english-words-2-22'),
	('They got buckets of water to put out the fire','Tất cả con vật liền lấy xô nước dập tắt ngọn lửa','00:01:13.400','00:01:17.000','4000-essential-english-words-2-22'),
	('A journalist came to write a story about the festival and the race','Một nhà báo đến để viết một câu chuyện về lễ hội và cuộc đua','00:01:17.000','00:01:21.300','4000-essential-english-words-2-22'),
	('The horse told her, "I am a special breed of horse"','Con ngựa nói với cô ấy, "Tôi là một giống ngựa đặc biệt"','00:01:21.300','00:01:25.100','4000-essential-english-words-2-22'),
	('"I would have won the race easily"','"Tôi có lẽ đã thắng cuộc đua dễ dàng"','00:01:25.100','00:01:27.800','4000-essential-english-words-2-22'),
	('The pig said, "It was somewhat hard to have the race"','Chú heo nói, "Cuộc đua có chút khó khăn"','00:01:27.800','00:01:31.800','4000-essential-english-words-2-22'),
	('"But we had fun"','" Nhưng chúng tôi đã rất vui"','00:01:31.800','00:01:33.000','4000-essential-english-words-2-22'),
	('"That is what\'s important"','"Đó mới là điều quan trọng"','00:01:33.000','00:01:35.800','4000-essential-english-words-2-22'),

	/* (UUID(),'4000-essential-english-words-2-23','The Clever Thief','Tên trộm thông minh','4000_ESSENTIAL_ENGLISH_WORDS_053.mp3',NULL,'00:00:00.000','00:01:33.200','4000-essential-english-words-2',0,0,53) */
	('A new king inherited a lot of gold','Một vị vua mới lên ngôi và được thừa kế rất nhiều vàng','00:00:03.000','00:00:06.200','4000-essential-english-words-2-23'),
	('He loved his gold very much','Ông ta rất quý trọng số vàng của mình','00:00:06.200','00:00:08.700','4000-essential-english-words-2-23'),
	('He even wanted to keep it after he died','Đến nỗi mà ông còn muốn đem theo số vàng đó xuống mồ','00:00:08.700','00:00:11.700','4000-essential-english-words-2-23'),
	('Therefore, he had a large tomb built for himself and his riches','Do đó, ông đã xây một cái hầm mộ lớn cho riêng mình và những của cải châu báu của mình','00:00:11.700','00:00:16.600','4000-essential-english-words-2-23'),
	('However, the tomb\'s builder had a plan','Tuy nhiên, người thợ xây hầm mộ đã có một kế hoạch riêng','00:00:16.600','00:00:20.000','4000-essential-english-words-2-23'),
	('Most of the stones were solid, but he put one special stone on the roof','Hầu hết những tảng đá thì nặng nhưng anh ta đã bí mật thay một tảng đá đặc biệt vào trần của hầm','00:00:20.000','00:00:25.700','4000-essential-english-words-2-23'),
	('It was made of a lighter substance','Tảng đá đó được làm bằng chất liệu nhẹ hơn','00:00:25.700','00:00:28.700','4000-essential-english-words-2-23'),
	('When the tomb was done, the king moved in his stock of gold','Khi hầm mộ được hoàn thiện, vị vua đã di chuyển đống vàng đó vào trong này','00:00:28.700','00:00:33.100','4000-essential-english-words-2-23'),
	('One night, the builder went to the tomb','Một đêm nọ, người thợ xây đến hầm mộ','00:00:33.100','00:00:36.800','4000-essential-english-words-2-23'),
	('His excitement mounted','Sự hào hứng của anh ta ngày càng tăng','00:00:36.800','00:00:38.900','4000-essential-english-words-2-23'),
	('Because all the stones looked alike, he had left a distinct mark on the artificial block','Bởi vì tất cả những viên đá dùng để xây mộ đều có hình dáng giống nhau nên anh ta đã để lại một cái dấu trên tảng đá nhân tạo của mình','00:00:38.900','00:00:45.000','4000-essential-english-words-2-23'),
	('The mark helped him distinguish the difference in the architecture','Cái dấu này giúp anh ta phân biệt được sự khác biệt trong kiến trúc','00:00:45.000','00:00:49.000','4000-essential-english-words-2-23'),
	('The builder lifted the stone','Người thợ xây nhấc tảng đá lên','00:00:49.000','00:00:51.800','4000-essential-english-words-2-23'),
	('Using a chain, he climbed into the tomb','Rồi anh dùng dây xích để trèo vào bên trong hầm mộ','00:00:51.800','00:00:55.200','4000-essential-english-words-2-23'),
	('He filled his pockets with gold','Ông đã nhét đấy vàng vào trong túi áo và túi quần của mình','00:00:55.200','00:00:57.900','4000-essential-english-words-2-23'),
	('The builder followed this manner night after night','Người thợ xây cứ thế làm theo cách như trên đêm này qua đêm khác','00:00:57.900','00:01:01.700','4000-essential-english-words-2-23'),
	('Soon, the king noticed a shortage in his gold','Chẳng mấy chốc mà vị vua đã để ý và thấy rằng số lượng vàng mà mình giữ đang hụt dần','00:01:01.700','00:01:05.600','4000-essential-english-words-2-23'),
	('This annoyed the king','Điều này đã khiến ông nổi giận','00:01:05.600','00:01:07.800','4000-essential-english-words-2-23'),
	('At last he hired a guard to hide inside the tomb','Cuối cùng, ông quyết định sử dụng lính canh rình bằng cách ẩn nấp trong hầm mộ','00:01:07.800','00:01:11.800','4000-essential-english-words-2-23'),
	('When the builder entered the tomb, the guard wounded him','Khi anh chàng thợ xây kia bước vào, lính gác đã tấn công và làm anh ta bị thương','00:01:11.800','00:01:15.800','4000-essential-english-words-2-23'),
	('He climbed a pole to the roof','Anh trèo lên đỉnh của hầm mộ','00:01:15.800','00:01:18.200','4000-essential-english-words-2-23'),
	('The builder left drops of blood in the dust','Anh ta thoát ra ngoài nhưng lại để lại những giọt máu rải dọc đường trong những đống cát','00:01:18.200','00:01:21.700','4000-essential-english-words-2-23'),
	('The guard followed them and caught him','Tên lính canh kia đuổi theo dấu máu và bắt được anh ta','00:01:21.700','00:01:24.200','4000-essential-english-words-2-23'),
	('When the builder healed, he explained to the king that he didn\'t keep any of the gold','Khi anh chàng thợ xây bình phục trở lại, anh giải thích với vị vua giàu có kia rằng anh đã không hề giữ bất cứ miếng vàng nào cả','00:01:24.200','00:01:29.800','4000-essential-english-words-2-23'),
	('He had given it all away to the poor','Thay vào đó, anh đã chia số vàng mà mình lấy được cho những người nghèo khó hơn','00:01:29.800','00:01:33.200','4000-essential-english-words-2-23'),

	/* (UUID(),'4000-essential-english-words-2-24','The Doctor\'s Cure','Việc chữa bệnh của bác sĩ','4000_ESSENTIAL_ENGLISH_WORDS_054.mp3',NULL,'00:00:00.000','00:01:38.600','4000-essential-english-words-2',0,0,54) */
	('James Fry was a fantastic doctor','James Fry là một bác sĩ tuyệt vời','00:00:03.000','00:00:06.400','4000-essential-english-words-2-24'),
	('His surgeries helped many disabled people overcome their injuries','Những ca phẫu thuật của ông đã giúp đỡ cho nhiều người khuyết tật vượt qua những chấn thương','00:00:06.400','00:00:10.700','4000-essential-english-words-2-24'),
	('He also wrote for a popular medical journal','Ông cũng viết cho một tạp chí y khoa nổi tiếng','00:00:10.700','00:00:13.800','4000-essential-english-words-2-24'),
	('James was very busy','James luôn bận rộn','00:00:13.800','00:00:16.000','4000-essential-english-words-2-24'),
	('His son, Steve, rarely saw him','Con trai ông, Steve, rất hiếm khi nhìn thấy ông','00:00:16.000','00:00:19.000','4000-essential-english-words-2-24'),
	('One day, James was walking and inspecting a patient\'s file','Một ngày nọ, ông đang đi bộ và kiểm tra hồ sơ bệnh nhân','00:00:19.000','00:00:23.800','4000-essential-english-words-2-24'),
	('There was water all over the floor','Có nước chảy trên sàn nhà','00:00:23.800','00:00:26.000','4000-essential-english-words-2-24'),
	('James slipped on the liquid and fell','James trượt chân và té','00:00:26.000','00:00:29.000','4000-essential-english-words-2-24'),
	('He fell on a broken glass tube','Ông ngã vào một ống thủy tinh đã vỡ','00:00:29.000','00:00:31.800','4000-essential-english-words-2-24'),
	('He was hurt','Ông bị thương','00:00:31.800','00:00:33.000','4000-essential-english-words-2-24'),
	('Steve came to visit him in the hospital','Steve đến bệnh viện thăm ông','00:00:33.000','00:00:35.900','4000-essential-english-words-2-24'),
	('James said, "It will be tough for me to stay in bed"','James nói, "Thật khó để cho bố có thể nằm trên giường"','00:00:35.900','00:00:40.200','4000-essential-english-words-2-24'),
	('"But I can hardly bend my legs"','"Và bố vẫn không thể gập được chân"','00:00:40.200','00:00:43.000','4000-essential-english-words-2-24'),
	('"Then let\'s watch a movie" Steve said','"Vậy giờ bố con mình xem phim nhé" Steve nói','00:00:43.000','00:00:46.000','4000-essential-english-words-2-24'),
	('It made them laugh together','Họ cười với nhau','00:00:46.000','00:00:48.000','4000-essential-english-words-2-24'),
	('Steve said, "I have to leave, but here\'s some fiction to read"','Steve nói, "Con phải về đây, con có để vài cuốn tiểu thuyết cho bố đọc"','00:00:48.000','00:00:52.800','4000-essential-english-words-2-24'),
	('James started to recall fun parts of life','James bắt đầu nhớ lại quãng thời gian hạnh phúc của mình','00:00:52.800','00:00:55.800','4000-essential-english-words-2-24'),
	('He marveled at small things, like food','Ông ngạc nhiên trước những điều tưởng chừng rất nhỏ nhặt, như thức ăn chẳng hạn','00:00:55.800','00:00:59.400','4000-essential-english-words-2-24'),
	('He was too busy to notice them before','Ông bận tới nỗi không có thời gian để ý đến chúng','00:00:59.400','00:01:02.000','4000-essential-english-words-2-24'),
	('"Steve," he said, "you get more nutrients when you chew slowly"','"Steve," Ông nói, "Khi con nhai kỹ, con sẽ hấp thụ được nhiều chất dinh dưỡng hơn đấy"','00:01:02.000','00:01:07.000','4000-essential-english-words-2-24'),
	('"But I think it makes food taste better, too"','"Và bố nghĩ nó cũng khiến thức ăn có mùi vị ngon hơn"','00:01:07.000','00:01:10.000','4000-essential-english-words-2-24'),
	('Weeks later, James said, "Steve, I haven\'t spent enough time with you"','Vài tuần sau, James nói: "Steve, bố đã không dành nhiều thời gian cho con"','00:01:10.000','00:01:15.400','4000-essential-english-words-2-24'),
	('"I regret this"','"Bố hối tiếc về điều này"','00:01:15.400','00:01:17.000','4000-essential-english-words-2-24'),
	('"Even my soul feels better when you visit"','"Thậm chí tâm hồn bố giờ đây cũng cảm thấy tốt hơn khi con đến thăm"','00:01:17.000','00:01:20.000','4000-essential-english-words-2-24'),
	('"But I have spent sufficient time here"','"Nhưng bố ở đây đủ rồi"','00:01:20.000','00:01:22.300','4000-essential-english-words-2-24'),
	('"We should go home"','"Giờ thì chúng ta về nhà thôi"','00:01:22.300','00:01:24.000','4000-essential-english-words-2-24'),
	('Outside, there was a warm breeze','Bên ngoài, một làn gió ấm áp thổi qua','00:01:24.000','00:01:26.700','4000-essential-english-words-2-24'),
	('James watched a flag blow','James nhìn lá cờ đang tung bay','00:01:26.700','00:01:29.200','4000-essential-english-words-2-24'),
	('Finally, James said, "I\'m not ready to work"','Cuối cùng, James nói, "Bố chưa sẵn sàng để bắt tay vào việc"','00:01:29.200','00:01:33.400','4000-essential-english-words-2-24'),
	('"I\'m going to take a long bath"','"Bố sẽ tắm rửa một chút"','00:01:33.400','00:01:35.600','4000-essential-english-words-2-24'),
	('"And then we\'ll watch a movie together"','"Và sau đó chúng ta sẽ cùng xem phim"','00:01:35.600','00:01:38.600','4000-essential-english-words-2-24'),

	/* (UUID(),'4000-essential-english-words-2-25','The Criminal','Tên tội phạm','4000_ESSENTIAL_ENGLISH_WORDS_055.mp3',NULL,'00:00:00.000','00:01:25.700','4000-essential-english-words-2',0,0,55) */
	('A man had been in jail because he stole things','Có một người đàn ông vào tù vì tội ăn cắp','00:00:02.600','00:00:05.800','4000-essential-english-words-2-25'),
	('The criminal never felt bad','Tên tội phạm không bao giờ cảm thấy tồi tệ','00:00:05.800','00:00:08.200','4000-essential-english-words-2-25'),
	('One day, he escaped and ran into the woods','Một ngày nọ, hắn trốn thoát và chạy vào rừng','00:00:08.200','00:00:11.500','4000-essential-english-words-2-25'),
	('He found a cabin with a fence','Ông tìm thấy một cái chòi với một cái hàng rào','00:00:11.500','00:00:14.000','4000-essential-english-words-2-25'),
	('The cabin was very neat','Cái chòi thì rất gọn gàng','00:00:14.000','00:00:15.800','4000-essential-english-words-2-25'),
	('Inside, the criminal found a bowl of fruit, a bottle of milk, and a dozen eggs','Vào bên trong, tên tội phạm tìm thấy một bát hoa quả, một hộp sữa và một tá trứng','00:00:15.800','00:00:22.000','4000-essential-english-words-2-25'),
	('He ate the fruit and drank the milk','Hắn ăn trái cây và uống sữa','00:00:22.000','00:00:24.300','4000-essential-english-words-2-25'),
	('But the eggs smelled funny, so he put them in the trash bin','Thế nhưng trứng có mùi rất buồn cười, vì vậy ông vất chúng vào thùng rác','00:00:24.300','00:00:28.400','4000-essential-english-words-2-25'),
	('Soon, he heard the sound of a vehicle\'s motor','Ngay sau đó, ông nghe thấy tiếng của động cơ xe hơi','00:00:28.600','00:00:32.000','4000-essential-english-words-2-25'),
	('An old man came in and saw the criminal','Một ông lão bước vào và nhìn thấy tất cả mọi việc','00:00:32.000','00:00:35.000','4000-essential-english-words-2-25'),
	('The old man yelled, "Why are you in my house?"','Ông hét lên, "Sao anh lại ở trong nhà tôi?"','00:00:35.000','00:00:38.400','4000-essential-english-words-2-25'),
	('The criminal lied, "I am a policeman"','Tên tội phạm nói dối, "Tôi là cảnh sát đây"','00:00:38.400','00:00:41.700','4000-essential-english-words-2-25'),
	('The old man replied, "I am your elder"','Ông lão đáp, "Tôi là người nhiều tuổi hơn anh"','00:00:41.700','00:00:44.800','4000-essential-english-words-2-25'),
	('"You cannot fool me"','"Anh không lừa được tôi đâu"','00:00:44.800','00:00:46.000','4000-essential-english-words-2-25'),
	('"You are the criminal"','"Anh là một tên trộm"','00:00:46.000','00:00:48.000','4000-essential-english-words-2-25'),
	('The criminal\'s facial expression became very sad','Vẻ mặt tên tội phạm biến thành rất buồn','00:00:48.000','00:00:51.800','4000-essential-english-words-2-25'),
	('He admitted that he was a criminal','Hắn thừa nhận hắn là tội phạm','00:00:51.800','00:00:54.300','4000-essential-english-words-2-25'),
	('He said, "I\'m sorry"','Hắn nói, "Tôi xin lỗi"','00:00:54.300','00:00:56.900','4000-essential-english-words-2-25'),
	('"It was rude for me to come into your home"','"Tôi thật bất lịch sự vì đã đột nhập vào nhà ông"','00:00:56.900','00:00:59.400','4000-essential-english-words-2-25'),
	('"Please take the cash from my wallet"','"Hãy cầm lấy tiền mặt trong ví tiền của tôi"','00:00:59.400','00:01:02.000','4000-essential-english-words-2-25'),
	('"It is a mere amount, but it will settle our problem"','"Đó chỉ là một ít tiền, nhưng nó sẽ giải quyết vấn đề của chúng ta"','00:01:02.000','00:01:05.800','4000-essential-english-words-2-25'),
	('The old man said, "I do not want your money"','Ông lão nói, "Tôi không cần tiền của anh"','00:01:05.800','00:01:09.200','4000-essential-english-words-2-25'),
	('"I just want to inspire you to be good"','"Tôi chỉ muốn truyền cảm hứng để anh sống tốt hơn"','00:01:09.200','00:01:12.300','4000-essential-english-words-2-25'),
	('"There will be no penalty for taking my food"','"Tôi sẽ không phạt anh vì đã lấy đồ ăn của tôi"','00:01:12.300','00:01:15.900','4000-essential-english-words-2-25'),
	('On this occasion, the criminal realized that he had been bad','Nhân dịp này, tên tội phạm nhận ra trước kia hắn xấu xa thế nào','00:01:15.900','00:01:20.200','4000-essential-english-words-2-25'),
	('He listened to the old man and never stole from anyone ever again','Hắn nghe lời ông lão và không bao giờ ăn cắp của bất cứ ai nữa','00:01:20.200','00:01:25.700','4000-essential-english-words-2-25');

