INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-2-26','The Two Captains','Hai ông thuyền trưởng','4000_ESSENTIAL_ENGLISH_WORDS_056.mp3',NULL,'00:00:00.000','00:01:29.800','4000-essential-english-words-2',0,0,56) */
	('Once there were two ships','Vào một lần nọ, có hai con tàu','00:00:03.300','00:00:05.400','4000-essential-english-words-2-26'),
	('Both ships carried cotton','Trên cả hai con tàu đó đều chở bông','00:00:05.400','00:00:07.600','4000-essential-english-words-2-26'),
	('The captains were very different','Hai ông thuyền trưởng này có tính cách trái ngược nhau','00:00:07.600','00:00:09.800','4000-essential-english-words-2-26'),
	('Thomas was strict','Thomas rất nghiêm khắc','00:00:09.800','00:00:11.500','4000-essential-english-words-2-26'),
	('He made his crew engage in difficult tasks','Ông đã đưa phi hành đoàn của ông tham gia vào nhiều nhiệm vụ khó khăn','00:00:11.500','00:00:14.600','4000-essential-english-words-2-26'),
	('"Make sure the ship\'s deck is firm and that nothing falls"','"“Hãy đảm bảo rằng boong tàu chắc chắn và không có cái gì rơi ra"','00:00:14.600','00:00:18.600','4000-essential-english-words-2-26'),
	('"Put more fuel in the tank" he said','"Và cho thêm nhiên liệu vào thùng" ông nói','00:00:18.600','00:00:21.800','4000-essential-english-words-2-26'),
	('His ship was very plain, but he never had a problem with it','Con tàu của ông nhìn rất thô sơ nhưng ông chưa bao giờ phàn nàn về nó cả','00:00:21.800','00:00:25.900','4000-essential-english-words-2-26'),
	('The second captain, William, was not serious','William, thuyền trưởng thứ hai, là người không nghiêm túc','00:00:25.900','00:00:29.800','4000-essential-english-words-2-26'),
	('He had a grand ship, and he loved having fun','Ông có một con tàu hoành tráng, và ông ta thích vui vẻ','00:00:29.800','00:00:33.100','4000-essential-english-words-2-26'),
	('His crew amused him by singing and dancing','Phi hàng đoàn của ông giúp ông giải trí bằng mấy cái trò ca hát, nhảy múa','00:00:33.100','00:00:36.700','4000-essential-english-words-2-26'),
	('But his crew never fixed anything on the ship','Nhưng họ không bao giờ cố định bất cứ thứ gì trên tàu','00:00:36.700','00:00:39.700','4000-essential-english-words-2-26'),
	('They just wanted to surf','Họ chỉ muốn lướt sóng','00:00:39.700','00:00:41.700','4000-essential-english-words-2-26'),
	('One day, Thomas saw a hurricane ahead','Một ngày nọ, Thomas nhìn thấy một cơn bão ở phía trước','00:00:41.700','00:00:44.900','4000-essential-english-words-2-26'),
	('He knew that his ship needed to turn around','Ông biết tàu của ông cần phải quay lại','00:00:44.900','00:00:47.800','4000-essential-english-words-2-26'),
	('But he was sure William did not see the storm','Nhưng ông chắc chắn William không nhìn thấy cơn bão','00:00:47.800','00:00:50.800','4000-essential-english-words-2-26'),
	('He adjusted the dials on the radio and called his friend','Ông đánh điện trên radio cho bạn mình','00:00:50.800','00:00:54.300','4000-essential-english-words-2-26'),
	('Thomas said, "You\'ll hit the reef"','Thomas nói, "Ông anh sẽ đâm vào đá ngầm đấy"','00:00:54.300','00:00:57.000','4000-essential-english-words-2-26'),
	('"It\'s made completely of coral"','"Chúng hoàn toàn là san hô"','00:00:57.000','00:00:59.000','4000-essential-english-words-2-26'),
	('"Turn around to ensure that you do not crash"','"Mau quay lại và đảm bảo anh không đâm sầm vào nó"','00:00:59.000','00:01:02.000','4000-essential-english-words-2-26'),
	('William said, "We will go under the deck and shut the door"','William nói, "Chúng tôi sẽ đi dưới boong tàu và đóng cửa lại"','00:01:02.000','00:01:06.700','4000-essential-english-words-2-26'),
	('"We will dance and sing until we are past the danger zone"','"Chúng tôi sẽ nhảy múa và ca hát cho đến khi qua vùng nguy hiểm"','00:01:06.700','00:01:10.200','4000-essential-english-words-2-26'),
	('When William\'s ship got to the hurricane, the wind blew it into the reef','Khi tàu của William gặp cơn bão, gió thổi con tàu va vào các đá ngầm','00:01:10.200','00:01:14.900','4000-essential-english-words-2-26'),
	('The ship crashed, and water flowed below the deck','Con tàu gặp nạn, và nước chảy xuống vào boong tàu','00:01:14.900','00:01:18.900','4000-essential-english-words-2-26'),
	('William\'s crew accused him of being a bad captain','Phi hành đoàn William đổ lỗi cho ông là một thuyền trưởng dở tệ','00:01:18.900','00:01:21.800','4000-essential-english-words-2-26'),
	('The loss of the ship taught William a lesson','Mất con tàu đã dạy cho William một bài học','00:01:21.800','00:01:24.800','4000-essential-english-words-2-26'),
	('There are times to have fun, but there are also times to be serious','Vui vẻ đúng lúc, nghiêm túc đúng nơi','00:01:24.800','00:01:29.800','4000-essential-english-words-2-26'),

	/* (UUID(),'4000-essential-english-words-2-27','The Duke and the Minister','Công tước và bộ trưởng','4000_ESSENTIAL_ENGLISH_WORDS_057.mp3',NULL,'00:00:03.800','00:01:35.800','4000-essential-english-words-2',0,0,57) */
	('A mean duke grew tobacco, and his cardinal rule was to always keep the plants healthy','Có một công tước trồng cây thuốc lá, và một nguyên tắc cốt lõi của ông là luôn giữ cho cây khỏe mạnh','00:00:03.800','00:00:10.800','4000-essential-english-words-2-27'),
	('The duke\'s top minister was his twin brother','Ngài bộ trưởng chính là người em trai song sinh của ông','00:00:10.800','00:00:14.000','4000-essential-english-words-2-27'),
	('They closely resembled each other','Họ rất giống nhau','00:00:14.000','00:00:16.200','4000-essential-english-words-2-27'),
	('One day, the tobacco plants started to die','Một ngày, những cây thuốc lá bắt đầu chết','00:00:16.200','00:00:19.800','4000-essential-english-words-2-27'),
	('He hired men to watch the fields','Vị công tước nọ thuê người để xem xét cánh đồng của mình','00:00:19.800','00:00:22.800','4000-essential-english-words-2-27'),
	('Soon, the men brought a woman to him and said, "We captured a witch"','Ngay sau đó, toán lính canh đưa một người phụ nữ đến trước mặt ông ta và nói rằng: "Chúng tôi đã bắt được một mụ phù thủy, thưa Ngài"','00:00:22.800','00:00:27.800','4000-essential-english-words-2-27'),
	('The Duke asked, "How do you know?"','Công tước hỏi, "Làm thế nào mà anh biết được điểu đó?"','00:00:27.800','00:00:30.800','4000-essential-english-words-2-27'),
	('"She sang magic words"','"Cô ta hát những lời ma thuật"','00:00:30.800','00:00:32.800','4000-essential-english-words-2-27'),
	('"I can\'t pronounce them"','Tôi không thể hiểu được','00:00:32.800','00:00:34.800','4000-essential-english-words-2-27'),
	('"She has cursed us"','"Cô ta nguyền rủa chúng tôi"','00:00:34.800','00:00:36.800','4000-essential-english-words-2-27'),
	('"The death of the plants is a symptom of her curse," the men said','"Cây cối chết là dấu hiệu của lời nguyền của ả", những người đàn ông nói','00:00:36.800','00:00:41.000','4000-essential-english-words-2-27'),
	('"I am just an ordinary woman"','','00:00:41.000','00:00:43.800','4000-essential-english-words-2-27'),
	('"I was singing a song in a different language," the woman protested','"Tôi chỉ đơn giản là ca những bài hát bằng những thứ tiếng khác nhau,", người phụ nữ cam đoan','00:00:43.800','00:00:48.800','4000-essential-english-words-2-27'),
	('The duke didn\'t listen','Vị công tước không hề lắng nghe','00:00:48.900','00:00:50.800','4000-essential-english-words-2-27'),
	('"You are guilty"','"Ngươi có tội"','00:00:50.800','00:00:51.800','4000-essential-english-words-2-27'),
	('"You will go to jail"','"Ngươi sẽ phải vào nhà lao"','00:00:51.800','00:00:53.800','4000-essential-english-words-2-27'),
	('The minister thoughfrthat she was innocent','Ông bộ trưởng lại nghĩ rằng người phụ nữ kia vô tội','00:00:53.800','00:00:56.800','4000-essential-english-words-2-27'),
	('He needed to expose the truth','Ông cần phải vạch trần sự thật này','00:00:56.800','00:00:59.000','4000-essential-english-words-2-27'),
	('He asked the duke to loan him one of his plants','Ông yêu cầu công tước cho ông mượn một cây thuốc lá','00:00:59.000','00:01:02.800','4000-essential-english-words-2-27'),
	('He looked at it closely','Ông nhìn nó say sưa','00:01:02.800','00:01:04.500','4000-essential-english-words-2-27'),
	('He saw hundreds of small bugs eating it','Ông quan sát thấy có hàng trăm con bọ nhỏ đang ăn thân cây','00:01:04.500','00:01:07.800','4000-essential-english-words-2-27'),
	('Then the ministerwent to the jail and did something bold','Sau đó, ngài Bộ trưởng đến thẳng nhà lao và thực hiện một điều táo bạo','00:01:07.800','00:01:12.800','4000-essential-english-words-2-27'),
	('"Let this woman go," he said','"Hãy thả người phụ nữ này ra ngay,", ông ra lệnh','00:01:12.800','00:01:14.800','4000-essential-english-words-2-27'),
	('The guards thought he was the duke','Lính canh nghĩ rằng ông là ngài Công tước','00:01:14.800','00:01:17.000','4000-essential-english-words-2-27'),
	('They let her go','Họ thả người phụ nữ ra','00:01:17.000','00:01:18.800','4000-essential-english-words-2-27'),
	('The minister said, "I owe you an apology"','"Tôi nợ cô một lời xin lỗi từ tận đáy lòng", Ngài Bộ trưởng nói','00:01:18.800','00:01:22.000','4000-essential-english-words-2-27'),
	('"Thank you"','Cảm ơn ngài','00:01:22.000','00:01:23.000','4000-essential-english-words-2-27'),
	('"I thought my stay in jail was permanent," the woman answered','Tôi cứ ngỡ rằng mình sẽ phải ở trong phòng giam này đến rũ xương trong này cả đời mất", người phụ nữ đáp lại','00:01:23.000','00:01:27.800','4000-essential-english-words-2-27'),
	('The minister thought the duke would punish him','Ngài Bộ trưởng lo ngại rằng vị Công tước sẽ trừng phạt ông','00:01:27.800','00:01:30.400','4000-essential-english-words-2-27'),
	('But he didn\'t','Nhưng ông ta đã không làm vậy','00:01:30.400','00:01:31.800','4000-essential-english-words-2-27'),
	('The duke was too busy trying to preserve his plants','Công tước đang bận rộn cố gắng cứu lấy những cái cây của mình','00:01:31.800','00:01:35.800','4000-essential-english-words-2-27'),

	/* (UUID(),'4000-essential-english-words-2-28','The Fisherman','Người ngư dân','4000_ESSENTIAL_ENGLISH_WORDS_058.mp3',NULL,'00:00:00.000','00:01:26.900','4000-essential-english-words-2',0,0,58) */
	('Every day, a fisherman sat on a bridge','Ngày nào cũng có một người ngư dân ngồi trên cây cầu','00:00:03.000','00:00:06.800','4000-essential-english-words-2-28'),
	('He ate apples and spit the seeds into the water','Ông ăn táo và nhổ hạt xuống nước','00:00:06.800','00:00:10.800','4000-essential-english-words-2-28'),
	('He had a simple way to catch fish','Ông có một cách đơn giản để bắt cá','00:00:10.800','00:00:13.100','4000-essential-english-words-2-28'),
	('He cut a branch off of a tree and tied a line to it','Ông bẻ một cành cây và buộc một sợi dây vào nó','00:00:13.100','00:00:17.300','4000-essential-english-words-2-28'),
	('He put a sharp hook on it and made a tight knot','Ông buộc một cái móc nhọn vào đầu còn lại và buộc chặt nó lại','00:00:17.300','00:00:20.800','4000-essential-english-words-2-28'),
	('Then he whispered, "Come here fish"','Sau đó, ông nói nhỏ, "Hãy đến đây, cá ơi"','00:00:20.800','00:00:23.800','4000-essential-english-words-2-28'),
	('Like magic, the fish bit the hook','Cứ như là có ma thuật vậy, cá cắn vào lưỡi câu','00:00:23.800','00:00:27.000','4000-essential-english-words-2-28'),
	('He put them in a big net and took them home to make big pots of fish soup from them','Ông nhốt chúng vào một cái lưới lớn và đem về nhà nấu súp cá','00:00:27.000','00:00:32.600','4000-essential-english-words-2-28'),
	('One day, another man walked up to him','Một ngày nọ, có một người đến chỗ ông ta','00:00:32.600','00:00:35.800','4000-essential-english-words-2-28'),
	('He said, "My name is George"','Anh ta nói: "Tôi là George"','00:00:35.800','00:00:38.700','4000-essential-english-words-2-28'),
	('"I am staying at the inn"','"Tôi đang ở một nhà trọ"','00:00:38.700','00:00:40.700','4000-essential-english-words-2-28'),
	('"I bet that I am a better fisherman than you"','"Tôi cá rằng tôi là một ngư dân giỏi hơn ông"','00:00:40.700','00:00:43.800','4000-essential-english-words-2-28'),
	('"I will accompany you today"','"Hôm nay tôi sẽ đi cùng ông"','00:00:43.800','00:00:45.800','4000-essential-english-words-2-28'),
	('"I dare you to prove your skill"','"Tôi thách ông chứng minh được khả năng của mình"','00:00:45.800','00:00:48.800','4000-essential-english-words-2-28'),
	('The fisherman cast his line','Người đánh cá thả dây câu','00:00:48.800','00:00:51.000','4000-essential-english-words-2-28'),
	('George had a lot of electronic tools','Geoge có rất nhiều công cụ bằng điện','00:00:51.000','00:00:54.000','4000-essential-english-words-2-28'),
	('One machine gave him the virtual locations offish','Một chiếc máy khiến anh ta tìm thấy gần như chính xác vị trí của cá','00:00:54.000','00:00:58.000','4000-essential-english-words-2-28'),
	('His rod weighed fish','Cần câu của anh cân được cá','00:00:58.000','00:01:00.000','4000-essential-english-words-2-28'),
	('At the end of the day, George subtracted his fish from the fisherman\'s','Vào cuối ngày, George trừ đi số cá của mình từ người ngư dân','00:01:00.000','00:01:05.600','4000-essential-english-words-2-28'),
	('The fisherman had beaten him by forty-seven','Người ngư dân đã đánh bại anh ta với tỉ lệ 40-7','00:01:05.600','00:01:08.800','4000-essential-english-words-2-28'),
	('George asked, "How do you catch fish with only a branch and a bare line?"','George hỏi, "Tại sao ông có thể bắt cá chỉ với một cành cây và một sợi dây?"','00:01:08.800','00:01:14.100','4000-essential-english-words-2-28'),
	('"I have many different sorts of tools"','Tôi có rất nhiều loại công cụ khác nhau','00:01:14.100','00:01:16.900','4000-essential-english-words-2-28'),
	('The fisherman told George, "My philosophy is simple"','Người đánh cá nói với George "Triết lý của tôi rất đơn giản"','00:01:16.900','00:01:20.900','4000-essential-english-words-2-28'),
	('"I am patient, and I believe in myself"','"Tôi là người kiên nhẫn và tôi tin vào bản thân mình"','00:01:20.900','00:01:23.900','4000-essential-english-words-2-28'),
	('"Take a breath, and try it my way"','"Hãy hít thở và làm theo cách của tôi"','00:01:23.900','00:01:26.900','4000-essential-english-words-2-28'),

	/* (UUID(),'4000-essential-english-words-2-29','Osiris and the Nile','Thần Osiris và dòng sông Nile','4000_ESSENTIAL_ENGLISH_WORDS_059.mp3',NULL,'00:00:00.000','00:01:38.200','4000-essential-english-words-2',0,0,59) */
	('Long ago, Osiris was the king of Egypt, and Isis was the queen','Ngày xưa, Osiris là vua của Ai Cập, còn Isis là nữ hoàng','00:00:03.500','00:00:08.400','4000-essential-english-words-2-29'),
	('They ruled the fertile land by the Nile River','Họ cai trị vùng sông Nile màu mỡ','00:00:08.400','00:00:12.100','4000-essential-english-words-2-29'),
	('They had great intelligence, and they shared their abstract ideas with everyone','Họ cực kì thông minh và họ chia sẻ những ý tưởng trừu tượng của mình với người dân','00:00:12.100','00:00:17.300','4000-essential-english-words-2-29'),
	('Osiris taught the Egyptians how to make wheels and furniture','Osiris dạy người Ai Cập cách làm bánh xe và đồ nội thất','00:00:17.300','00:00:22.100','4000-essential-english-words-2-29'),
	('Isis taught them how to make things from clay and cloth','Isis dạy họ cách làm từ đất sét và vải','00:00:22.100','00:00:25.900','4000-essential-english-words-2-29'),
	('The people thought they deserved a gift','Người dân nghĩ rằng họ xứng đáng nhận được một món quà','00:00:25.900','00:00:28.200','4000-essential-english-words-2-29'),
	('So they built Osiris and Isis a pyramid','Vì vậy họ xây dựng một kim tự tháp cho Osiris và Isis','00:00:28.200','00:00:31.400','4000-essential-english-words-2-29'),
	('Everyone loved Osiris except his brother, Set','Mọi người đều yêu mến Osiris trừ anh trai của ông, Set','00:00:31.400','00:00:35.300','4000-essential-english-words-2-29'),
	('Set wanted to be king','Set muốn làm vua','00:00:35.300','00:00:37.300','4000-essential-english-words-2-29'),
	('Osiris made his annual trip around Egypt and led religious events','Osiris thực hiện chuyến đi hàng năm của mình vòng quanh Ai Cập và tổ chức các sự kiện về tôn giáo','00:00:37.300','00:00:42.900','4000-essential-english-words-2-29'),
	('The villages gave him beautiful shells and colorful feathers as gifts','Dân làng lấy vỏ sò và lông vũ đầy màu sắc để làm quà tặng ông','00:00:42.900','00:00:47.400','4000-essential-english-words-2-29'),
	('When Osiris returned, Set brought a beautiful wooden box from behind a curtain','Khi Osiris trở về, Set mang một hộp bằng gỗ tuyệt đẹp từ phía sau tấm rèm','00:00:47.400','00:00:53.100','4000-essential-english-words-2-29'),
	('"If someone fits inside this box, I will give it to him or her," Set said','"Ai chui vào vừa chiếc hộp này, tôi sẽ tặng cho người đó," Set nói','00:00:53.100','00:00:59.100','4000-essential-english-words-2-29'),
	('Osiris got in it','Osiris chui vào','00:00:59.100','00:01:00.900','4000-essential-english-words-2-29'),
	('It was an ideal fit','Quả là vừa khít','00:01:00.900','00:01:02.900','4000-essential-english-words-2-29'),
	('Suddenly, Set closed the box and threw it into the river','Đột nhiên Set đóng chiếc hộp lại và quăng nó xuống sông','00:01:02.900','00:01:07.400','4000-essential-english-words-2-29'),
	('"Now I will be king," Set said','"Từ giờ ta sẽ chính là vua," Set nói','00:01:07.400','00:01:11.000','4000-essential-english-words-2-29'),
	('The box washed up on a foreign shore after a flood','Chiếc hộp trôi dạt vào một bờ biển của nước khác sau trận lũ','00:01:11.000','00:01:15.000','4000-essential-english-words-2-29'),
	('Isis brought his body home and obtained a grave for him in Egypt','Isis mang cơ thể chồng mình về nhà và xây cho ông ngôi mộ ở Ai Cập','00:01:15.000','00:01:19.800','4000-essential-english-words-2-29'),
	('The Egyptian gods thought Isis had done something very romantic','Các vị thần Ai Cập nghĩ hành động của Isis thật cảm động','00:01:19.800','00:01:24.800','4000-essential-english-words-2-29'),
	('Because of her love, the gods made him the god of the underworld','Vì tình yêu của bà, thần linh đã để ông trở thành vị thần của thế giới ngầm','00:01:24.800','00:01:29.200','4000-essential-english-words-2-29'),
	('Osiris returned every spring to help the farmers','Osiris trở lại vào mỗi mùa xuân để giúp đỡ người nông dân','00:01:29.200','00:01:33.200','4000-essential-english-words-2-29'),
	('Even nowadays, people say Osiris keeps their crops alive','Thậm chí ngày nay, người ta vẫn tin rằng thần Osiris giúp cho cây trồng của họ luôn tươi tốt','00:01:33.200','00:01:38.200','4000-essential-english-words-2-29'),

	/* (UUID(),'4000-essential-english-words-2-30','The Taxi Driver','Tài xế taxi','4000_ESSENTIAL_ENGLISH_WORDS_060.mp3',NULL,'00:00:00.000','00:01:32.800','4000-essential-english-words-2',0,0,60) */
	('Peter\'s job was driving a taxi downtown','Công việc của Peter là một tài xế taxi ở trung tâm thành phố','00:00:03.500','00:00:06.800','4000-essential-english-words-2-30'),
	('He made a small salary','Anh ấy kiếm được một khoản lương nhỏ','00:00:06.800','00:00:08.800','4000-essential-english-words-2-30'),
	('But he liked his job because it wasn\'t dull','Tuy nhiên anh thích công việc này vì nó không hề buồn tẻ','00:00:08.800','00:00:12.200','4000-essential-english-words-2-30'),
	('Every day, he saw new things that appealed to him','Ngày nào, anh ấy cũng thấy những điều mới mẻ hấp dẫn mình','00:00:12.200','00:00:15.200','4000-essential-english-words-2-30'),
	('Peter was practical about the future','Peter rất thực tế về tương lai','00:00:15.200','00:00:17.900','4000-essential-english-words-2-30'),
	('"Maybe I can get a scholarship to college," he thought','"Tôi có thể nhận được một học bổng để đi học đại học," anh ấy đã nghĩ','00:00:17.900','00:00:21.100','4000-essential-english-words-2-30'),
	('"I could learn mathematical formulas and get a job at a bank"','"Tôi có thể học về các công thức toán học và kiếm một công việc trong ngân hàng"','00:00:21.100','00:00:25.300','4000-essential-english-words-2-30'),
	('"I could help clients invest their money"','"Tôi có thể giúp khách hàng đầu tư tiền của họ"','00:00:25.300','00:00:28.200','4000-essential-english-words-2-30'),
	('Peter stopped to pick up a passenger','Peter dừng lại đón một hành khách','00:00:28.200','00:00:30.800','4000-essential-english-words-2-30'),
	('"Where to?" he asked','"Anh đi đâu?", anh ấy hỏi','00:00:30.800','00:00:33.800','4000-essential-english-words-2-30'),
	('"Go to the Fourth Street Bank"','"Hãy tới ngân hàng Fourth Street"','00:00:33.800','00:00:35.200','4000-essential-english-words-2-30'),
	('"And don\'t talk to me"','Và đừng nói chuyện gì với tôi hết','00:00:35.200','00:00:36.800','4000-essential-english-words-2-30'),
	('"I\'ve had a rough day," the man said','"Tôi đã có một ngày căng thẳng," người đàn ông nói','00:00:36.800','00:00:39.800','4000-essential-english-words-2-30'),
	('Peter was angry, but he had a peaceful philosophy','Peter hơi tức giận, nhưng anh ấy có một triết lý sống ôn hòa','00:00:39.800','00:00:43.800','4000-essential-english-words-2-30'),
	('When they stopped, the man\'s fare came to $10.25','Khi họ dừng lại, cước phí của người khách đó lên đến 10,25 đô la','00:00:43.800','00:00:48.000','4000-essential-english-words-2-30'),
	('He put his hands in his pockets','Ông ta thò tay vào các túi quần của mình','00:00:48.000','00:00:50.800','4000-essential-english-words-2-30'),
	('"I can\'t find my wallet" he said','"Tôi không thể tìm thấy ví của mình", ông ấy nói','00:00:50.800','00:00:53.800','4000-essential-english-words-2-30'),
	('"I can\'t pay the fare"','"Tôi không thể trả tiền phí"','00:00:53.800','00:00:55.800','4000-essential-english-words-2-30'),
	('Peter said, "Maybe I\'ll give you a temporary loan"','Peter nói, "Tôi sẽ cho anh vay một một khoản tạm thời"','00:00:55.800','00:00:59.800','4000-essential-english-words-2-30'),
	('"You can borrow ten dollars and a quarter from me"','Anh có thể mượn tôi 10,25 đô la','00:00:59.800','00:01:02.800','4000-essential-english-words-2-30'),
	('The man was embarrassed, saying, "I was mean to you, but now I want to help you"','Người đàn ông rất xấu hổ, ông ấy nói, "Tôi đã tỏ ra thật ích kỷ, nhưng bây giờ tôi muốn giúp anh"','00:01:02.800','00:01:08.300','4000-essential-english-words-2-30'),
	('"I founded this bank"','"Chính tôi đã thành lập ngân hàng này"','00:01:08.300','00:01:10.000','4000-essential-english-words-2-30'),
	('"I want to give you one thousand dollars"','"Tôi muốn tặng cho anh một nghìn đô la"','00:01:10.000','00:01:12.800','4000-essential-english-words-2-30'),
	('That much money was like a treasure to Peter','Số tiền đó nhiều như một kho báu đối với Peter','00:01:12.800','00:01:15.800','4000-essential-english-words-2-30'),
	('The man urged him to take the money, but he didn\'t','Người đàn ông cứ hối thúc Peter nhận số tiền đó nhưng anh ấy đã không làm vậy','00:01:15.800','00:01:19.100','4000-essential-english-words-2-30'),
	('"You\'re an honest person," the man said','"Anh là một người thật thà," người đàn ông nói','00:01:19.100','00:01:22.000','4000-essential-english-words-2-30'),
	('"I assumed you would take it"','"Tôi đã cho rằng anh sẽ nhận nó"','00:01:22.000','00:01:23.800','4000-essential-english-words-2-30'),
	('"I want you to work for me"','Tôi muốn anh làm việc cho tôi','00:01:23.800','00:01:25.800','4000-essential-english-words-2-30'),
	('The next day, Peter started his job at the bank','Ngày hôm sau, Peter bắt đầu công việc tại ngân hàng','00:01:25.800','00:01:29.800','4000-essential-english-words-2-30'),
	('He was happy to be done with his former job','Anh ấy rất hạnh phúc vì đã làm tốt với công việc cũ của mình','00:01:29.800','00:01:32.800','4000-essential-english-words-2-30');
